import React from "react";
import styled from "styled-components";
import { WindowsIcon, AndroidIcon, IosIcon, LinuxIcon } from "public/static/redesign/os-icon";

const SVGContainer = styled.span`
    display: flex;
    align-items: center;
    justify-content: center;
    margin-left: 4px;

    svg {
        min-width: 12px;
        min-height: 12px;
        width: 12px;
        height: 12px;
    }
`

export const getOsIcon = (os: string) => {
    switch (os) {
        case "Windows":
            return (
            <SVGContainer>
                <WindowsIcon/>
            </SVGContainer>);
        case "Android":
            return (
            <SVGContainer>
                <AndroidIcon/>
            </SVGContainer>
            );
        case "iOS":
        case "Mac OS":
        case "MacOS":
        case "Macintosh":
            return (
            <SVGContainer>
                <IosIcon/>
            </SVGContainer>
            );
        case "Linux":
            return (
            <SVGContainer>
                <LinuxIcon/>
            </SVGContainer>
            );
        default:
            return null;
    }
}