import React, { useMemo } from 'react'
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext';
import { useIsAppType } from './useIsAppType';

function useHasSmartEvents():boolean {
    const isWebApp = useIsAppType('web');
    const { noCodeEventsFeatureFlag } = useNoCodeEventsContext();
    const hasSmartEvent = useMemo(()=> noCodeEventsFeatureFlag && !isWebApp, [noCodeEventsFeatureFlag, isWebApp]);
    return Boolean(hasSmartEvent)
}

export default useHasSmartEvents