import React, { useCallback, useState } from 'react';

import { Button, Form } from 'antd';

import {StyledModal, FormContainer} from './styles';

import { TModalProps } from './types';

const CustomModal: React.FC<TModalProps> = ({
    title,
    subtitle,
    children,
    isModalOpen,
    handleOk,
    handleCancel,
    disabled,
    loading,
    hideButtons,
    containerClassName,
    actionButtonTitles,
    form
}) => (
    <StyledModal
        visible={isModalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        centered
        footer={null}
        closable={false}
    >
        <span className={containerClassName}>
            {
                title ? <h2>{title}</h2> : null
            }
            {
                subtitle ? <p>{subtitle}</p> : null
            }
        </span>

        <FormContainer form={form} onFinish={handleOk}>
        {children}

        {hideButtons ? null : (
            <div className="modal-footer">
                <Button
                    onClick={() => {
                    handleCancel();
                    }}
                    type="link"
                >
                    {actionButtonTitles?.cancel || 'Cancel'}
                </Button>
                <Button
                    type="primary"
                    htmlType="submit"
                    disabled={disabled}
                    loading={loading}
                >
                    {actionButtonTitles?.ok || 'Ok'}
                </Button>
            </div>
        )}
        </FormContainer>
    </StyledModal>
);

const useCommonModal = () => {
    const [openModal, setOpenModal] = useState(false);
    const [ form ] = Form.useForm();

    const CommonModal:React.FC<TModalProps> = useCallback((
        {
            children,
            title,
            subtitle,
            handleOk = () => null,
            handleCancel,
            disabled,
            loading,
            hideButtons,
            containerClassName,
            actionButtonTitles,
        }
    ) => (
        <CustomModal 
            isModalOpen={openModal}
            title={title}
            subtitle={subtitle}
            handleOk={handleOk}
            handleCancel={() => {
                handleCancel && handleCancel();
                setOpenModal(false);
            }}
            disabled={disabled}
            loading={loading}
            hideButtons={hideButtons}
            containerClassName={containerClassName}
            actionButtonTitles={actionButtonTitles}
            form={form}
        >
            {children}
        </CustomModal>
    ), [openModal, form])

    return {
        openModal,
        setOpenModal,
        CommonModal,
        formRef: form,
    }
}

export default useCommonModal; 