export const formattedFilters = 
(appliedFilters) => appliedFilters?.length && appliedFilters.map(segmentData => {
  const formattedSement = {...segmentData}
  if(formattedSement?.attribute === 'event_count_per_screen_visit' || formattedSement?.attribute === 'smart_event_count_per_screen_visit'){
    const newFilters =  segmentData?.filters
   const eventNameFilter = newFilters?.length > 0 &&  newFilters?.find(filter=> filter?.attribute === 'event_name' || filter?.attribute === 'nce_name')
   if(eventNameFilter && eventNameFilter?.value?.length === 0){
    formattedSement.filters =  newFilters.filter(filter=> filter?.attribute !== 'event_name' && filter?.attribute !== 'nce_name')
   }
  }

  return formattedSement
});