import React, { useCallback, useEffect, useMemo, useState } from "react";
import { useSelector } from "react-redux";
import {
    useFetchActiveSubscription,
  } from 'components/features/setting/useSettingPage';

import UpgradeModal from "components/features/sessions/SessionDetailsAndVideo/Toolbar/UpgradeModal";
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext';
import { showIntercom } from "Utils/constants";

export const useCheckExportPlan = () => {
    const [upgradePlan, setUpgradePlan] = useState(false);
    const { currentAppReducer } = useSelector((state) => state);
    const { orgId } = currentAppReducer;
    const { setShowPricingModal, selfServeFlag } = useRestrictionContext();

    const {
        data: activeSubscription,
        refetch: refetchActiveSubscription,
        error: apiError,
        isError: isApiError,
    } = useFetchActiveSubscription(orgId);
    
    const exportCSV = activeSubscription?.planFeature?.exportCsv;
    const status = activeSubscription?.status;

    const canExportData = useMemo(() => !!((status === 'Active' || status === 'Canceled') && exportCSV === 1), [status, exportCSV]);

    const handleUpgrade = useCallback(() => {
        setUpgradePlan(false);
        setShowPricingModal(true);
    }, [setShowPricingModal]);
    
    const handleGetinTouch = () => {
    showIntercom();
    };

    useEffect(() => {
        refetchActiveSubscription()
    }, [orgId]);

    const CommonUpgradeModal = useCallback(() => (
            <UpgradeModal
                upgradePlan={upgradePlan}
                handleGetinTouch={handleGetinTouch}
                handleUpgrade={handleUpgrade}
                handleCancel={() => setUpgradePlan(false)}
                acceptText={selfServeFlag ? 'See pricing' : 'Request pricing'}
            />
        ), [upgradePlan, handleUpgrade, selfServeFlag])

    return {
        canExportData,
        CommonUpgradeModal,
        apiError,
        isApiError,
        setUpgradePlan,
        upgradePlan,
    }
}