/* eslint-disable react/jsx-props-no-spreading */
import React, { memo } from 'react';
import styled from 'styled-components';
import { useSelector } from 'react-redux';
import { Tooltip } from 'antd';
import Cookies from 'universal-cookie'
import { useQueryClient } from 'react-query';
import { rollbar } from 'components/common/rollbar'

import MarkLabelCell from 'components/common/MarkLabelCell';
import { NoteIcon } from 'components/svg_files/index';
import {
  getSessionsUserId,
  getSessionsUploadDate,
} from 'components/common/CustomLabelModal';
import { useCustomLabelApi } from 'hooks/useCustomLabels';
import { useSessionTableHelper } from '../../utils';

const browserCookies = new Cookies()

const Wrapper = styled.div`
  width: 100%;
  display: flex;
  align-items: center;
  gap: 14px;

  #outside-icon-box {
    padding-left: 0;

    .ant-badge-count {
      display: none;
    }
  }
  background-color: ${props => props?.isActive ? '#DFEAFF' : ''};
`;

const UnreadIndicator = styled.div`
  height: 6px;
  width: 6px;
  border-radius: 50%;
  background-color: ${({ unread }) => (unread ? '#DC4F44' : '#D0D2D7')};
`;

const Icons = styled.div`
  display: flex;
  flex-direction: column;
  justify-content: center;
`;

const LabelIconWrapper = styled.div`
  position: relative;
`;

const NoteIconWrapper = styled.div`
  position: relative;

  svg {
    max-width: 14px;
    path{
      fill:#49576E;
    }
  }
`;

const CountLabel = styled.div`
  position: absolute;
  top: -2px;
  right: -5px;
  height: 13px;
  width: 13px;
  padding: 4px;
  font-size: 0.5rem;
  color: #ffffff;
  background-color: #5D97FF;
  border-radius: 50%;
  display: flex;
  justify-content: center;
  align-items: center;
  pointer-events: none;
`;

const TableRowCheckCell = ({ row, expanded }) => {
  const sessionNotesCount = row?.original?.sessionNotesCount;
  const sessionid = row?.original?.sessionid;
  const customLabel = row?.original?.customLabel;
  const isUnread = !row?.original?.isViewed;
  const sessionLocked = row?.original?.sessionLocked;
  const queryClient = useQueryClient();
  const { markSessionLabel } = useCustomLabelApi();
  const { handleRowClick } = useSessionTableHelper({ expanded });

  const { currentAppReducer, urlReducer: urlQuery } = useSelector((state) => state);
  const { _id } = currentAppReducer;
  let sessionQueryKey = ''
  try {
    sessionQueryKey = ['sessionItems', JSON.parse(localStorage.getItem('sessionsListReqBody'))]
  } catch (err) {
    // silent fail
  }
  const cookieFromAdmin = browserCookies.get('loggedInFromAdminDashboard');

  const handleIndicatorClick = async () => {
    const id = row?.original?.sessionid;
    if (id && cookieFromAdmin !== '1'){
      const selectedSession =[row.original.sessionid]
      const requestData = {
        customLabelName: 'isViewed',
        isTagged: isUnread,
        sessionIds: selectedSession,
        labelType: 'session',
      };
      const sessionResponse = queryClient.getQueryData(sessionQueryKey);
      const queryList = sessionResponse?.data?.data?.body || [];

      let sessionUserIds = getSessionsUserId(selectedSession, queryList, 'sessionid');
      let sessionUploadDate = getSessionsUploadDate(selectedSession, queryList, 'sessionid');
      
      const allSessionCaches = queryClient.getQueriesData(['sessionItems']);
      const sessionFromAllCaches = allSessionCaches?.[0]?.[1]?.data?.data?.body

      if (!sessionUserIds?.length || !sessionUploadDate?.length) {
        sessionUserIds = getSessionsUserId(selectedSession, sessionFromAllCaches, 'sessionid');
        sessionUploadDate = getSessionsUploadDate(selectedSession, sessionFromAllCaches, 'sessionid');
      }

      const payload = {
        ...requestData,
        appid: _id,
        uxcamuserIds: sessionUserIds,
        uploadedOn: sessionUploadDate,
        debugSource: 2,
        debugCacheLen: queryList?.length,
        debugAltCacheLen: sessionFromAllCaches?.length,
      };
      markSessionLabel(payload)
     
      queryClient.setQueryData(sessionQueryKey, (old) => {
        const newBody = old.data.data.body.map((el) => {
              if (selectedSession.includes(el.sessionid)) {
                return {
                  ...el,
                  isViewed: isUnread,
                };
              }
              return el;
            });

          return {
            ...old,
            data: {
              ...old.data,
              data: {
                ...old.data.data,
                body: newBody,
              },
            },
          };
        }
      );
    }
  };

  return (
    <Wrapper isActive={urlQuery?.sessionid === sessionid} className='icon-wrapper'>
      <Tooltip
        placement="top"
        title={ isUnread ? 'Mark as read' : 'Mark as unread'}
        visible={ sessionLocked ? false : undefined }
      >
        <UnreadIndicator unread={isUnread} onMouseDown={ !sessionLocked ? handleIndicatorClick : undefined } />
      </Tooltip>
      { !sessionLocked && (
        <input
          type="checkbox"
          aria-label="Select row"
          {...{
            checked: row.getIsSelected(),
            indeterminate: row.getIsSomeSelected(),
            disabled: !row.getCanSelect(),
            onChange: row.getToggleSelectedHandler(),
          }}
        />
      )}
      <Icons>
        <LabelIconWrapper>
          <MarkLabelCell
            data={row?.original}
            locked={ sessionLocked }
            index={row?.index}
          />
          {customLabel?.length > 0 && (
            <CountLabel>{customLabel.length}</CountLabel>
          )}
        </LabelIconWrapper>
        <NoteIconWrapper
          onMouseDown={ !sessionLocked ? (e) => handleRowClick(e, sessionid, !isUnread, true) : () => null}
        >
          <NoteIcon/>
            {sessionNotesCount > 0 && <CountLabel>{sessionNotesCount}</CountLabel>}
        </NoteIconWrapper>
      </Icons>
    </Wrapper>
  );
};

export default memo(TableRowCheckCell);
