/* eslint-disable import/no-named-as-default */
import React, { useState } from 'react';
import { Button, Menu, Dropdown, message } from 'antd';
import { useSelector, useDispatch } from 'react-redux';
import { CloudDownloadOutlined, DeleteOutlined } from '@ant-design/icons';
import styled from 'styled-components';
import { any, useMutation, useQueryClient } from 'react-query';

import DeleteSessionBox from 'components/common/deleteSession';
import { axiosInstance } from 'services/globalInstance';
import { fetchPlanHatApi } from 'redux/actions/common';
import { getSessionIdWithDate } from 'Utils/helpers/SessionUtils';
import { useSessionTimeLine } from 'components/shared/Sessions/Context';
import CommonLimitModal from 'components/shared/Sessions/CommonModal';
import useIssueListAPI from 'components/features/issues/hooks/useIssueListAPIs';

const MenuItem = Menu.Item;

const ButtonRound = styled.button`
  border: none;
  background-color: #FFFFFF;
  transition: all 0.2s ease;
  border-radius: 50%;
  height: 24px;
  width: 24px;
  padding: 0;
  margin: 0;
  margin-left: 8px;
  cursor: pointer;
  &:hover {
    background-color: #EFF5FF !important;
  }
  img {
    margin-top: -2px;
  }
`
const ButtonRound2 = styled.button`
    border: none;
    background: #F3F4F5;
    border-radius: 50%;
    height: 24px;   
    width: 24px;
    display: flex;
    justify-content: center;
    align-items: center;
    cursor: pointer;
    path {
        fill: #5D97FF;
    }
`

const TopRightMenu = styled.div`
  li {
    &:hover {
      background: transparent;
    }
    .ant-dropdown-menu-title-content {
      .ant-btn {
        box-shadow: none !important;
      }
    }
  }
`;

const OptionButton = styled(Button)`
  border: none;
`;

const SessionOption = ({alternativeStyle=false, passedSessionId=''}) => {
  const dispatch = useDispatch();
  const { issueListDetailQueryKey } = useIssueListAPI();
  const queryClient = useQueryClient();
  let sessionList = ''
  let aiSessionList = ''
  let eventList = ''
  try {
    sessionList = queryClient.getQueryData(['sessionItems', JSON.parse(localStorage.getItem('sessionsListReqBody'))]);
    aiSessionList = queryClient.getQueryData(['aiSessionItems', JSON.parse(localStorage.getItem('aiSessionsListReqBody'))]);
    eventList = queryClient.getQueryData(['eventList', JSON.parse(localStorage.getItem('eventsListReqBody'))]);
  } catch (err) {
    // silent fail
  }
  const issueDetailList = queryClient.getQueryData(issueListDetailQueryKey);
  
  const { sessionDetail, setVideoLimitPopup, videoLimitPopup } =
    useSessionTimeLine();
  const [deleteModalVisible, setDeleteModalVisible] = useState(false);

  const { urlReducer: urlQuery, currentOrgReducer: currentOrg, profileReducer: user, } = useSelector(
    (state) => state
  );

  const { name } = user;

  const { appId, sessionid, shareSessionKey } = urlQuery;

  const sessionId = passedSessionId || sessionid;

  const { mutate: deleteIndividualSession, isLoading: deleteLoading } =
    useMutation(
      (data) =>
        axiosInstance({
          method: 'POST',
          url: `${process.env.DB_API_URL}/deletion_requests`,
          data,
          withCredentials: true,
        }),
      {
        onSuccess: () => {
          setDeleteModalVisible(false);
          message.success('Session is deleted successfully');
          let url;
          const urlTypeVal = {
            sessionsList: 'sessions/list',
            usersList: 'users/list',
            screensList: 'heatmaps/list',
            eventsList: 'events/list',
            aiSessionsList: 'aisessions/list',
          };
          if (urlQuery.parentType === 'issues') {
            url = `${process.env.REDIRECT_URL}/app/${urlQuery.appId}/issues/${urlQuery.issueType}/${urlQuery.issuepage}/${urlQuery.issueid}`;
          } else {
            url = `${process.env.REDIRECT_URL}/app/${urlQuery.appId}/${
              urlTypeVal[urlQuery.parentType]
            }`;
          }
          window.location.href = url;
        },
        onError: async (err) => {
          if (!err?.response?.data?.success) {
            await message.error(err?.response?.data?.error?.message);
          }
          setDeleteModalVisible(false);
        },
      }
    );
  const deleteSession = async () => {
    let queryList;
    if (urlQuery?.parentType === 'sessionsList') {
      queryList = sessionList?.data?.data?.body;
    } else if (urlQuery?.parentType === 'eventsList') {
      queryList = eventList?.data?.data?.body;
    } else if (urlQuery?.parentType === 'issues') {
      queryList = issueDetailList?.data?.data?.body;
    } else if (urlQuery?.parentType === 'aiSessionsList') {
      queryList = aiSessionList?.data?.data?.body;
    }
    // const queryList = urlQuery?.parentType === 'sessionsList' ? sessionList?.data?.data?.body : eventList?.data?.data?.body
    const identifiers = getSessionIdWithDate([sessionId], queryList);
    deleteIndividualSession({
      table_name: 'session',
      app_id: appId,
      requested_by_user_name: name,
      identifiers,
    });
  };

  const onCancel = () => {
    setDeleteModalVisible(false);
  };

  const downloadVideo = () => {
    if (
      !sessionDetail?.isPlayable ||
      sessionDetail?.verifiedPastVideoRecordingLimit
    ) {
      setVideoLimitPopup(!videoLimitPopup);
      return;
    }
    if (!sessionDetail?.isPlayable) {
      message.info(
        <span>
          Please{' '}
          <a
            style={{ textDecoration: 'underline' }}
            href={`${process.env.REDIRECT_URL}/settings/org/${currentOrg?.orgId}/plan`}
          >
            upgrade your plan
          </a>{' '}
          to enable this feature or get in touch with the customer success team.
        </span>,
        5
      );
      return;
    }
    dispatch(fetchPlanHatApi({ action: 'Video downloaded' }));
    setTimeout(() => {
      window.open(sessionDetail?.downloadableLink, '_blank', 'noopener,noreferrer');
    }, 100);
  };

  const menu = () => (
    <Menu>
      <TopRightMenu>
        {
          sessionDetail?.device?.platform === 3 ? (
            null
          ) : (
            <MenuItem key="download">
              <OptionButton onClick={() => downloadVideo()}>
                <CloudDownloadOutlined /> Download video
              </OptionButton>
            </MenuItem>
          )
        }
        {!shareSessionKey && (
          <MenuItem key="delete">
            <>
              <DeleteSessionBox
                title="Delete Session?"
                content="Do you want to delete this session? This action is irreversible."
                onOk={deleteSession}
                onCancel={onCancel}
                deleteLoading={deleteLoading}
                deleteModalVisible={deleteModalVisible}
              />
              <OptionButton onClick={() => setDeleteModalVisible(true)}>
                <DeleteOutlined /> Delete session
              </OptionButton>
            </>
          </MenuItem>
        )}
      </TopRightMenu>
    </Menu>
  );

  return (
    <>
      <Dropdown overlay={menu} trigger={['hover']}>
        {
        alternativeStyle ?
        <ButtonRound2 data-intercom-target="Session options">
            <img src="/static/sessions/threeDot.svg" alt="" />
        </ButtonRound2>
            :
        <ButtonRound data-intercom-target="Session options">
          <img src="/static/sessions/threeDot.svg" alt="" />
        </ButtonRound>
        }
      </Dropdown>
      {videoLimitPopup && <CommonLimitModal />}
    </>
  );
};

export default SessionOption;
