import { useState, useMemo } from 'react';

// types
import { PaginationState } from '@tanstack/react-table';

export const usePagination = () => {
    const [{ pageIndex, pageSize }, setPagination] = useState<PaginationState>({
      pageIndex: 1,
      pageSize: 1,
      // totalPagination: 2, 
    });
    // Note: the page size is 1 and not 20 because the backend only sends the total pages and not the total data
    // so when sending totalPagination with the BE pages data the appropriate page size will be calculated

    const pagination = useMemo(
      () => ({
        pageIndex,
        pageSize,
      }),
      [pageIndex, pageSize]
    );

    return {
        pagination,
        setPagination,
    }
}