export function formatNumberWithCommas(input) {
  let x = input;
  if (typeof input === 'number') {
    x = input.toString();
  }

  if (typeof x !== 'string') {
    return 'Invalid input';
  }

  const parts = x.split('.');
  parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');

  return parts.join('.');
}

export function containsOnlyNumbers(str) {
  if(/^\d+$/.test(str)) {
    return formatNumberWithCommas(str)
  }
  return str;
}