import { useCallback, useMemo } from 'react';
import Router from 'next/router';

import Cookies from 'universal-cookie';
import { useQueryClient } from 'react-query';
import { rollbar } from 'components/common/rollbar';
import { useDispatch, useSelector } from 'react-redux';
import { trackPageViews } from 'redux/actions/trackingReport';

import { useCustomLabelApi } from 'hooks/useCustomLabels';
import { useVideoRef } from 'components/shared/Sessions/Context/videoContext';
import {
  useSessionSidebar,
  useSessionVideoContext,
  useSessionVideoControlls,
} from 'components/shared/Sessions/Context';
import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder';
import {
  getSessionsUserId,
  getSessionsUploadDate,
} from 'components/common/CustomLabelModal';
import { goToPage } from 'components/shared/Pagination';


const browserCookies = new Cookies();

export const useSessionTableHelper = ({ expanded }) => {
  const {
    currentAppReducer,
    urlReducer: urlQuery,
    appFilter,
  } = useSelector((state) => state);
  const eventSegment = appFilter?.event?.segment;
  const sessionSegment = appFilter?.session?.segment;
  const dateSegment = appFilter?.dateSegment;
  const { _id: appid } = currentAppReducer;
  const { sessionpage, sessionid: sessionIdURL } = urlQuery;
  const segment = useMemo(() => {
    const mapSegment = { eventsList: eventSegment, sessionsList: sessionSegment, aiSessionsList: sessionSegment };
    return mapSegment[urlQuery.parentType] || [];
  }, [eventSegment, sessionSegment, urlQuery.parentType]);
  const {
    appId,
    autoplay: autoplayURL,
    parentType,
    eventid,
    starttime,
    uxcamuserid,
    notetab,
  } = urlQuery;
  const sessionPage = useMemo(() => Number(sessionpage), [sessionpage]);

  const dispatch = useDispatch();
  const queryClient = useQueryClient();

  const { setSelectedTab } = useSessionSidebar();
  const { userTime } = useSessionVideoContext();
  const { videoElemRef } =
    useSessionVideoControlls();
  const videoRef = useVideoRef();
  const { markSessionLabel } = useCustomLabelApi();
  const cookieFromAdmin = browserCookies.get('loggedInFromAdminDashboard');

  const navigatePage = useCallback(
    (newPage) => {
      const url = `/app/${appid}/sessions/list/${
        newPage || 1
      }/${sessionIdURL}?`;
      const query = `appId=${appid}&parentType=sessionsList&sessionid=${sessionIdURL}&sessionpage=${
        newPage || 1
      }&starttime=0#autoplay`;
      Router.push(`/integration?${query}`, url);
    },
    [sessionIdURL, appid]
  );

  const handleViewedSession = (id) => {
    let sessionQueryKey = ''
    try {
      sessionQueryKey = [
        'sessionItems',
        JSON.parse(localStorage.getItem('sessionsListReqBody')),
      ];
    } catch (err) {
      // silent fail
    }

    const selectedSession = [id];
    const requestData = {
      customLabelName: 'isViewed',
      isTagged: true,
      sessionIds: selectedSession,
      labelType: 'session',
    };
    const sessionResponse = queryClient.getQueryData(sessionQueryKey);
    const queryList = sessionResponse?.data?.data?.body || [];

    let sessionUserIds = getSessionsUserId(selectedSession, queryList, 'sessionid');
    let sessionUploadDate = getSessionsUploadDate(selectedSession, queryList, 'sessionid');
    
    const allSessionCaches = queryClient.getQueriesData(['sessionItems']);
    const sessionFromAllCaches = allSessionCaches?.[0]?.[1]?.data?.data?.body

    if (!sessionUserIds?.length || !sessionUploadDate?.length) {
      sessionUserIds = getSessionsUserId(selectedSession, sessionFromAllCaches, 'sessionid');
      sessionUploadDate = getSessionsUploadDate(selectedSession, sessionFromAllCaches, 'sessionid');
    }
    
    const payload = {
      ...requestData,
      appid,
      uxcamuserIds: sessionUserIds,
      uploadedOn: sessionUploadDate,
      debugSource: 3,
      debugCacheLen: queryList?.length,
      debugAltCacheLen: sessionFromAllCaches?.length,
    };  
    
    const isEmptyObj  = (v) => v != null && !Array.isArray(v) && typeof v === "object" && Object.keys(v).length === 0;
    const isEmptyArr  = (v) => Array.isArray(v) && v.length === 0;
    const isNil       = (v) => v == null; // null or undefined
    const isEmpty     = (v) => isNil(v) || isEmptyArr(v) || isEmptyObj(v);

    try {
      const missingUserIds     = isEmpty(sessionUserIds);
      const missingUploadDate  = isEmpty(sessionUploadDate);

      if (missingUserIds || missingUploadDate) {
        rollbar.error("cant find required fields", {
          source: 3,
          missing: { sessionUserIds: missingUserIds, sessionUploadDate: missingUploadDate },
          sessionQueryKey,
          selectedSession,
          queryList,
          sessionResponse,
          payload,
        });
      }
    } catch (err) {
      rollbar.error("cant find required fields - catch error", {
        source: 31,
        message: err instanceof Error ? err.message : String(err),
        name: err instanceof Error ? err.name : undefined,
      });
    }
    markSessionLabel(payload);

    queryClient.setQueryData(sessionQueryKey, (old) => {
      if (!old?.data?.data?.body) {
        return old
      }

      const newBody = old.data.data.body.map((el) => {
        if (selectedSession.includes(el.sessionid)) {
          return {
            ...el,
            isViewed: true,
          };
        }
        return el;
      });

      return {
        ...old,
        data: {
          ...old.data,
          data: {
            ...old.data.data,
            body: newBody,
          },
        },
      };
    });
  };

  const buildSessionUrl = useCallback(
    (sessionId, secondarysessionid, startTime = 0, autoplay = false,) => {
      const autoPlayPart = autoplay ? '#autoplay' : '';
      const availableSecondarySessionId = secondarysessionid || sessionId;
      const timePathPart = startTime ? `/${startTime}` : '';
      let url = `/app/${appid}/aisessions/list/${ sessionpage || 1 }/${sessionId}${timePathPart}?secondarysessionid=${availableSecondarySessionId}&`
      url = `${urlSegmentEncoder(url, [ ...segment, ...[{ ...dateSegment }], ])}${autoPlayPart}`;
      return url;
    },
    [appid, sessionpage, segment, dateSegment, parentType]
  );

  const onItemSetActive = useCallback(
    (sessionId, autoplay, isViewed, secondarysessionid, startTime = 0) => {
      const autoPlayPart = autoplay ? '#autoplay' : '';
      if (isViewed && cookieFromAdmin !== '1'){
        handleViewedSession(sessionId );
      }
      const availableSecondarySessionId = secondarysessionid || sessionId;
      // Include startTime in URL path if non-zero
      const timePathPart = startTime ? `/${startTime}` : '';
      let url = `/app/${appid}/aisessions/list/${ sessionpage || 1 }/${sessionId}${timePathPart}?secondarysessionid=${availableSecondarySessionId}&`
      url = `${urlSegmentEncoder(url, [ ...segment, ...[{ ...dateSegment }], ])}${autoPlayPart}`;
      const query = `appId=${appid}&parentType=aiSessionsList&sessionid=${sessionId}&secondarysessionid=${availableSecondarySessionId}&sessionpage=${
        sessionpage || 1
      }&starttime=${startTime}${autoPlayPart}`;
      Router.push(`/integration?${query}`, url);
      return url
    },
    [markSessionLabel, appid, sessionpage, segment, dateSegment, parentType]
  );

  const trackUserTimeEvent = useCallback(
    (sessionId, timer) => {
      expanded &&
        dispatch(
          trackPageViews(null, {
            eventName: 'session_replay_stopped',
            track_type: 'event',
            eventProperty: {
              sessionId,
              userTime: timer || userTime,
              duration: videoRef?.current?.duration,
            },
          })
        );
    },
    [dispatch, expanded, userTime, videoRef]
  );

  const onItemPlay = useCallback(
    // eslint-disable-next-line default-param-last
    (sessionId, playing = false, isViewed, timer) => {
      onItemSetActive(sessionId, playing, !isViewed);
      if (videoElemRef?.current) videoElemRef.current.play().catch( () => null );
      if (expanded)
        dispatch(
          trackPageViews(null, {
            eventName: 'open_session_replay',
            track_type: 'event',
            eventProperty: {},
          })
        );
    },
    [dispatch, expanded, onItemSetActive, videoElemRef]
  );
  const onItemPause = useCallback(
    (sessionId) => {
      onItemSetActive(sessionId, false);
      if (videoElemRef?.current) videoElemRef.current.pause();
    },
    [onItemSetActive, videoElemRef]
  );
  const handleUserClick = useCallback(
    (userId) => {
      // e.stopPropagation();

      let sessionDetail = sessionIdURL ? `1/${sessionIdURL}` : `1`;
      const url = `/app/${appid}/users/list/1/${userId}/session/${sessionDetail}`;
      sessionDetail = sessionIdURL ? `&sessionid=${sessionIdURL}` : '';
      const query = `appId=${appid}&type=session&parentType=usersList&uxcamuserid=${userId}&userpage=1&sessionpage=1&sort=ture${sessionDetail}`;
      Router.push(`/integration?${query}`, `${url}`);
    },
    [appid, sessionIdURL]
  );

  const handleRowClick = async (e, sessionId, isViewed, isNote) => {
    const sessionid = sessionId?.props?.children || sessionId;
    expanded &&
      dispatch(
        trackPageViews(null, {
          eventName: 'open_session_replay',
          track_type: 'event',
          eventProperty: {},
        })
      );
    if (e.button === 0) onItemSetActive(sessionid, false, isViewed);
    isNote && setSelectedTab('notes');
  };

  const pageChange = async (page) => {
    if (sessionPage !== page) {
      dispatch(trackPageViews(null, {
        eventName: 'navigate_sessions_table',
        track_type: 'event',
        eventProperty: {
          currentPage: page
        }
      }))
      goToPage({
        page,
        appId,
        sessionid: sessionIdURL,
        autoplayURL,
        segment,
        parentType,
        eventid,
        starttime,
        expanded,
        uxcamuserid,
        notetab,
        dateSegment: sessionIdURL && dateSegment
      });
    }
  };

  return {
    buildSessionUrl,
    handleRowClick,
    handleUserClick,
    handleViewedSession,
    navigatePage,
    onItemPlay,
    onItemPause,
    onItemSetActive,
    trackUserTimeEvent,
    pageChange,
  };
};
