export const platformMapper = {
  1: 'android',
  2: 'apple',
  3: 'desktop',
}

export const platformDisplayMapper = {
  1: 'Android',
  2: 'iOS',
  3: 'Desktop',
}

const ColumnSelection = memo(({ cell, row }) => {
  const {
    urlReducer: urlQuery,
  } = useSelector((state) => state);

  const { sessionid: sessionIdURL } = urlQuery;
  
  const {
    column: { id, isCustomUserProperty }
  } = cell;

  const {
    sessionid,
    userProperty: user,
    sessionDuration,
    userSessionRun,
    sessionUploadedDateTime,
    deviceLocalDateTime,
    city,
    country,
    countryCode,
    platform,
    deviceModel,
    deviceClass,
    uniqueScreensCount,
    crashed,
    totalEvent,
    totalGesture,
    osVersion,
    rageGestureCount,
    video,
    isViewed,
    onItemPlay,
    onItemPause,
    handleUserClick,
    sessionLocked,
    browserName,
    browserVersion,
    deviceType,
    deviceHeight,
    deviceWidth,
    deviceOsName,
  } = row.original;

  if(has(user, removeUxCamCustomProperty(id))){
    return <Cell>
        <EllipseText>
        {user[removeUxCamCustomProperty(id)] || 'N/A'}
        </EllipseText>
      </Cell>
  }

  switch (id) {
    case 'sessionhashofuser':
      return <SessionListItem
        key={sessionid}
        user={user}
        duration={sessionDuration}
        sessionsNum={userSessionRun}
        sessionId={sessionid}
        onPlay={onItemPlay}
        onPause={onItemPause}
        selectedItem={sessionIdURL}
        video={video}
        isViewed={isViewed}
        sessionLocked={ sessionLocked }
      />
    case 'sessiondate':
    case 'recordedon':
      return <HorizontalCell>
        <div className="when-date title">
          {getDifferenceFromNow( id === 'recordedon' ? deviceLocalDateTime : sessionUploadedDateTime)}
          <StyledSpan className="subtitle">
            {formatDisplayTime(
              id === 'recordedon' ? deviceLocalDateTime : sessionUploadedDateTime,
              'ddd, MMMM DD, hh:mm A'
            )}
          </StyledSpan>
        </div>
      </HorizontalCell>
    case 'timeforuser':
      return <Cell className="user-date title">
        {moment(deviceLocalDateTime).format('MMM DD, YYYY')}
        <StyledSpan className="subtitle">
          {moment(deviceLocalDateTime).format('ddd, hh:mm  a')}
        </StyledSpan>
      </Cell>
    case 'city':
      return <HorizontalCell>
        <div className="city title">
          {city}
          <StyledSpan className="subtitle">{country}</StyledSpan>
        </div>
        <div className="flag">
          {countryCode ? <ReactCountryFlag svg countryCode={countryCode} /> : null}
        </div>
      </HorizontalCell>

    case 'devicemodel': {
      const tempDeviceType = platformMapper[platform];
      const deviceModelFormatted = deviceModel.includes('iPhone') || deviceModel.includes('iPad')
        ? getRenamedDeviceName(deviceModel)
        : deviceModel.toUpperCase();

      return <HorizontalCell>
        <div className="platform-icon">
          {
            tempDeviceType === 'desktop' ? <p>D</p>
            : <Icon type={tempDeviceType} />
          }
        </div>

        <StyleSpan>{deviceModelFormatted}</StyleSpan>
      </HorizontalCell>
    }
    case 'country':
      return <HorizontalCell>
        <StyledSpanCountry>{country}</StyledSpanCountry>
      </HorizontalCell>

    case 'uniquescreenscount':
      return <Cell>{containsOnlyNumbers(uniqueScreensCount)}</Cell>
    case 'crashed':
      return <Cell>{crashed ? 'Yes' : 'No'}</Cell>
    case 'eventcount':
      return <Cell>{containsOnlyNumbers(totalEvent)}</Cell>
    case 'totalgesture':
      return <Cell>{containsOnlyNumbers(totalGesture)}</Cell>
    case 'ragegesturecount':
      return <Cell>{containsOnlyNumbers(rageGestureCount)}</Cell>

    case 'osversion':
      return <Cell>
        {osVersion}{platform === 3 ? '' :`(${platformDisplayMapper[platform]})`}
      </Cell>

    case 'duration': {
      const sessionDurationFormatted = sessionDuration < 60 ? `${Math.round(sessionDuration)} sec` : convertGetTime({durationInSecs: sessionDuration});
      return <Cell>{sessionDurationFormatted}</Cell>
    }
    case 'userdevice': {
      const userIdConfig = getUserId({
             customUserId: user?.kUXCam_UserIdentity,
             uxcamuserid: user?.uxcamuserid,
           });
      return (<Cell>
              {!userIdConfig?.customUserId ? (
                  <Tooltip
                      placement="topLeft"
                      title={
                          <span>
                              {userIdConfig?.info}
                          </span>
                      }
                  >
                      <button className="text-italic-asterisk" type="button"
                          onMouseDown={() => handleUserClick(user.uxcamuserid)}>
                          {userIdConfig?.uxcamuserid}
                      </button>
                  </Tooltip>
              ) : (
                  <button type="button"
                      onMouseDown={() => handleUserClick(user.uxcamuserid)}>
                      {userIdConfig?.customUserId}
                  </button>
              )}
      </Cell>)
    }
    case 'platform':
      return <Cell>{platformDisplayMapper[platform]}</Cell>

    case 'deviceclass': {
      const deviceClassUpdated = deviceClass.includes('iPhone') || deviceClass.includes('iPad')
        ? getRenamedDeviceName(deviceClass)
        : deviceClass;
      return <Cell>{deviceClassUpdated}</Cell>
    }

    case 'sessionid':
      return <HorizontalCell><StyleSpan>{sessionid}</StyleSpan></HorizontalCell>

    case 'browsername':
      return <Cell>
        {browserName || 'N/A'}
      </Cell>
    
    case 'browserversion':
      return <Cell>{browserVersion || 'N/A'}</Cell>
    
    case 'devicetype':
      return <Cell>{deviceType || 'N/A'}</Cell>

    case 'deviceheight':
      return <Cell>{deviceHeight}</Cell>
    
    case 'devicewidth':
      return <Cell>{deviceWidth}</Cell>

    case 'deviceosname':
      return <HorizontalCell>{deviceOsName || 'N/A'} {getOsIcon(deviceOsName)}</HorizontalCell>

    default: 
      return <Cell>
        {
          isCustomUserProperty ? 'N/A' : containsOnlyNumbers(row.original[keyMap[id]]) || containsOnlyNumbers(row.original[id]) || '-'
        }
      </Cell>
  }
});

export default function useSessionColumns(headers, expanded) {
  const {
    urlReducer: urlQuery,
  } = useSelector((state) => state);

  const { sessionid: sessionIdURL } = urlQuery;
  const columnHelper = createColumnHelper();

  const sessionTableTooltip = useMemo(
    () => ({
      sessiondate: `Time since the session was uploaded.(UTC ${getOffsetTimeFromUTC()})`,
    }),
    []
  );

  const columnsAreInDefaultState = useMemo(
    () =>
      headers
        ?.map((header) =>
          defaultColumns.find((column) => column === header.attribute)
            ? header.isVisible
            : !header.isVisible
        )
        .every((x) => x),
    [headers]
  );
  const columns = useMemo(() => (headers)
    .map((header) => {
      const {
        isVisible,
        attribute,
        title,
        titleInfo: tooltip,
        smallSessionTable,
        isSortable,
        isCustomUserProperty,
      } = header;
      const titleInfo = sessionTableTooltip.hasOwnProperty(attribute)
        ? sessionTableTooltip[attribute]
        : tooltip;
      return isVisible &&
        attribute !== 'video' &&
        (sessionIdURL
          ? attribute === 'sessiondate'
            ? false
            : smallSessionTable
          : true)
        ? columnHelper.accessor(attribute, {
            header: isCustomUserProperty ? (
              <Tooltip placement="top" title={titleInfo}>
                <EllipseTitle>
                  <em>{ stripCustomPropertyAndMapLabel(title) }</em>
                </EllipseTitle>
              </Tooltip>
            ) : (
              <Tooltip placement="top" title={titleInfo}>
                <EllipseTitle>{title}</EllipseTitle>
              </Tooltip>
            ),
            cell: ({ cell, row }) => <ColumnSelection cell={cell} row={row} />,
            accessor: attribute,
            titleInfo,
            size: 180,
            enableResizing: true,
            minSize: 180,
            maxSize: 360,
            enableSorting: isSortable,
            isCustomUserProperty,
          })
        : null;
    })
    .filter((el) => el), [headers, sessionTableTooltip, sessionIdURL, columnsAreInDefaultState]);
  
  const columnsWithSelect = useMemo(() => [
    {
      id: 'select',
      disableResizing: true,
      minWidth: 35,
      width: 35,
      maxWidth: 35,
      header: ({ table }) => (
        <CheckBoxWrapper>
          <TableCheckbox
            {...{
              checked: table.getIsAllRowsSelected(),
              indeterminate: table.getIsSomeRowsSelected(),
              onChange: table.getToggleAllRowsSelectedHandler(),
            }}
          />
        </CheckBoxWrapper>
      ),
      cell: ({ row }) => (
        <TableRowCheckCell
          row={row}
          expanded={expanded}
        />
      ),
    },
    ...columns,
  ], [columns, expanded]);
  return columnsWithSelect;
}