export default function timeLineRandomColor(str) {
  let rgb
  const colors = [
    '#EECA93',
    '#BD489C',
    '#4F6996',
    '#4E9BAE',
    '#02343F',
    '#815854',
    '#1AAFBC',
    '#0063B2',
    '#CBCE91',
    '#B1624E',
    '#7B9ACC',
    '#603F83',
    '#004020',
    '#0080E0',
    '#800060',
    '#2CAE66',
    '#FFD662',
    '#CF8360',
    '#DF6589',
    '#4B878B',
    '#BD7F37',
    '#F96167',
    '#F9D141',
    '#CCF381',
    '#8BD8BD',
    '#F3A94F',
    '#348597',
    '#307773',
    '#800020',
  ]

  let hash = 0
  if (str.length === 0) return hash
  for (let i = 0; i < str.length; i++) {
    hash = str.charCodeAt(i) + ((hash << 5) - hash)
    hash &= hash
  }
  hash = ((hash % colors.length) + colors.length) % colors.length
  rgb = colors[hash]
  return rgb
}

export function timeLineSequentialColor(index) {
    const sequentialColors = [
        "#FED64D", // Dandelion
        "#FE909F", // Pink Salmon
        "#846388", // Lilac Bush
        "#31DFA6", // Shamrock
        "#FFA265", // Light Salmon
        "#F09CDD", // Lavender Rose
        "#3DD3DD", // Aquamarine Blue
        "#FDBB3A", // Buttercup
        "#FF73A5", // Persian Pink
        "#699CD9", // Jordy Blue
        "#4ABD86", // Ocean Green
        "#FF6E65", // Salmon
        "#CE7BE1", // Lavender
        "#7BC0F1", // Malibu
        "#F3B2A9"  // Rose Bud
        ]
    return sequentialColors[index % sequentialColors.length]
}
