import React, { useState, useEffect, useMemo } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { Icon as LegacyIcon } from '@ant-design/compatible';
import { useQueryClient } from 'react-query';
import {
  CheckOutlined,
  DeleteOutlined,
  DownOutlined,
  EditOutlined,
  SearchOutlined,
} from '@ant-design/icons';
import { Form, Button, Input, Dropdown, Popconfirm } from 'antd';
import { gotUserDetail } from 'redux/actions/userList/actionObjects'

import useCustomLabels, { useCustomLabelApi } from 'hooks/useCustomLabels';
import { antIcons } from 'components/svg_files/CustomLabelSvgIcon';

import {StyledModal} from './styles';

const FormItem = Form.Item;

const CustomLabelManageModel = (props) => {
  const dispatch = useDispatch();
  const queryClient = useQueryClient();
  const [form] = Form.useForm();
  const {
    urlReducer: urlQuery,
    currentAppReducer,
    userDetailReducer,
  } = useSelector((state) => state);

  const { isModalVisible, modelHide } = props;
  const { _id } = currentAppReducer;
  const { data: userDetails } = userDetailReducer;

  const { sessionid, uxcamuserid, parentType } = urlQuery;

  const {
    megaFilterSessionLabels,
    userLabels,
  } = useCustomLabels();

  const { deleteLabel, updateLabel } = useCustomLabelApi();

  const customLabels = useMemo(() => parentType === 'usersList' ? userLabels : megaFilterSessionLabels, [parentType, userLabels, megaFilterSessionLabels])

  const [orderedCustomLabels, setOrderedCustomLabels] = useState(customLabels);
  const [editIcon, setEditIcon] = useState();
  const [key, setKey] = useState();
  const [selectedIcon, setSelectedIcon] = useState(undefined);
  const [previousIcon, setPreviousIcon] = useState();
  const [searchValue, setSearchValue] = useState();

  const labelOnUserDetail = userDetails?.customLabel || [];
  const sessionKey = parentType === 'aiSessionsList' ? 'aiSessionItems' : 'sessionItems'
  const sessionBodyKey = parentType === 'aiSessionsList' ? 'aiSessionsListReqBody' : 'sessionsListReqBody'
  let queryKey = '';
  try {
    queryKey =
      parentType === 'usersList'
        ? ['userList', JSON.parse(localStorage.getItem('usersListReqBody'))]
        : [ sessionKey, JSON.parse(localStorage.getItem(sessionBodyKey)),];
  } catch (err) {
    // silent fail
  }
  const sessionQueryKey = useMemo(() => `${sessionid}`, [sessionid]);
  const isUserList = parentType === 'usersList';

  const updateUserDetail = (labelName) => {
    const newUserDetail = { ...userDetails };
    newUserDetail.customLabel = labelOnUserDetail?.filter(
      (label) => label !== labelName
    );
    dispatch(gotUserDetail(newUserDetail));
  };

  const handleDeleteLabel = (data) => {
    const labelName = data?.customLabelName;
    const labelType = isUserList ? 'user' : 'session';
    const dataV2 = {
      ...data,
      appid: _id,
      labelType,
    };
    deleteLabel(dataV2).then(() => {
      const filteredLabels = customLabels.filter(label => label.name !== labelName);
      if (filteredLabels.length === 0) {
        modelHide();
      }
    })

    queryClient.setQueryData(queryKey, (old) => {
      const newBody = old.data.data.body.map((el) => ({
        ...el,
        customLabel: el.customLabel.filter((label) => label !== labelName),
      }));
      return {
        ...old,
        data: {
          ...old.data,
          data: {
            ...old.data.data,
            body: newBody,
          },
        },
      };
    });

    if (uxcamuserid && parentType === 'usersList') {
      updateUserDetail(labelName);
    }

    if (urlQuery?.sessionid && [ 'sessionsList', 'aiSessionsList' ].includes( urlQuery.parentType ) ) {
      const sessionDetailResponse = queryClient.getQueryData(sessionQueryKey);
      const sortedCustomField = sessionDetailResponse?.customLabel
        .filter((label) => label !== labelName)
        .sort();
      sessionDetailResponse.customLabel = sortedCustomField;
      queryClient.setQueryData(sessionQueryKey, sessionDetailResponse);
    }
  };

  const handleIconClick = async (icon) => {
    setSelectedIcon(icon);
    await setEditIcon(icon);
  };

  const handleClose = () => {
    setEditIcon();
    setKey();
  };

  const handleEditIcon = async (value, keyVal) => {
    await setEditIcon(value.icon);
    setKey(keyVal);
    setSelectedIcon(value.icon);
    setPreviousIcon(value.icon);
  };

  const handleDeleteIcon = async (value) => {
    const filterLabel = customLabels.filter((obj) => obj.name !== value.name);
    filterLabel.sort((a, b) =>
      a.name.localeCompare(b.name)
    );

    const combinedData = {
      customLabelName: value.name,
    };
    handleDeleteLabel(combinedData);
  };

  const handleEditCustomLabel = (name) => {
    const data = {
      labelIcon: previousIcon,
      updatedLabelIcon: selectedIcon,
      customLabelName: name,
      labelType: isUserList ? 'user' : 'session',
    };

    const dataV2 = data;
    dataV2.appid = _id;
    updateLabel(dataV2)

    setKey();
    setSelectedIcon();
    setPreviousIcon();
    setSearchValue();
  };

  const handleCustomLabelSearch = (e) => {
    setSearchValue(e.target.value);
    const searchResult =
      customLabels &&
      customLabels.filter(
        (obj) =>
          obj.name.toLowerCase().indexOf(e.target.value.toLowerCase()) >= 0
      );
    setOrderedCustomLabels(searchResult);
  };

  const iconLibrary = (
    <div className="icon-wrapper-box">
      <ul className="label-icon-list">
        {antIcons &&
          antIcons.map((item) => (
            <li
              key={item.type}
              className={item.type === selectedIcon ? 'icon-selected' : ''}
            >
              <a>
                <LegacyIcon
                  type={item.type}
                  onClick={() => handleIconClick(item.type)}
                />
              </a>
            </li>
          ))}
      </ul>
    </div>
  );
  const iconLibraryDropdown = (
    <Dropdown
      overlay={iconLibrary}
      overlayClassName="icon-library-dropdown"
      trigger={['click']}
      onClick={(e) => e.preventDefault()}
    >
      <a style={{ color: '#161E35' }}>
        <LegacyIcon type={editIcon} /> <DownOutlined />
      </a>
    </Dropdown>
  );

  useEffect(() => {
    let searchResult = [];
    if (searchValue) {
      searchResult =
        customLabels &&
          customLabels.filter(
            (obj) =>
              obj.name.toLowerCase().indexOf(searchValue.toLowerCase()) >= 0
      ); 
    } else {
      searchResult = customLabels;
    }
    
    setOrderedCustomLabels(searchResult);
  }, [customLabels]);

  return (
    <StyledModal
      visible={isModalVisible}
      onCancel={modelHide}
      afterClose={handleClose}
      destroyOnClose
      closable
      footer={null}
    >
      <section>
        <h3 className='modal-title'>Manage {parentType === 'usersList' ? 'user' : 'session'} labels</h3>
        {customLabels && customLabels.length > 20 && (
          <FormItem className="label-search-box">
            <SearchOutlined />
            <Input
              placeholder="Search custom label"
              value={searchValue}
              onChange={handleCustomLabelSearch}
            />
          </FormItem>
        )}
        <Form
          form={form}
          onFinish={null}
          hideRequiredMark
          className="custom-scrollbar"
        >
          {orderedCustomLabels instanceof Array &&
            orderedCustomLabels.map((label, index) => (
              <div key={label.name}>
                <FormItem className="label-viewonly">
                  {editIcon && key === index ? (
                    <FormItem
                      style={{ width: '100%' }}
                    >
                      <Input
                        addonBefore={iconLibraryDropdown}
                        addonAfter={
                          <Button
                            type="primary"
                            icon={<CheckOutlined />}
                            onClick={() => handleEditCustomLabel(label.name)}
                          />
                        }
                        placeholder="Enter label name"
                        value={label.name}
                        disabled
                      />
                    </FormItem>
                  ) : (
                    <>
                      <div className="icon-box">
                        <LegacyIcon type={label.icon} />
                      </div>
                      <div className="label-name">{label.name}</div>
                      <div className="label-action">
                        <Button
                          icon={<EditOutlined />}
                          onClick={() => handleEditIcon(label, index)}
                        />
                        <Popconfirm
                          overlayClassName="delete-pop-confirm"
                          onConfirm={() => handleDeleteIcon(label, index)}
                          title="Are you sure you want to delete?"
                          okText="Delete"
                          icon={null}
                          cancelText="Cancel"
                        >
                          <Button icon={<DeleteOutlined />} />
                        </Popconfirm>
                      </div>
                    </>
                  )}
                </FormItem>
              </div>
            ))}
        </Form>

        {/* <section className='modal-footer'>
          <Button key="submit" type="" onClick={modelHide}>
            Close
          </Button>
        </section> */}
      </section>
    </StyledModal>
  );
};

export default CustomLabelManageModel;
