const useSchematicReplay = () => {
    let localShowSchematicReplayModal = false
    try {
        localShowSchematicReplayModal = Boolean(localStorage.getItem('showSchematicReplayModal'));
    } catch (err) {
        // silent fail
    }
    
    const setSchematicReplayModal = (value: boolean) => {
        try {
            localStorage.setItem('showSchematicReplayModal', JSON.stringify(value));
        } catch (err) {
            // silent fail
        }
    }
    return { localShowSchematicReplayModal, setSchematicReplayModal}
}

export default useSchematicReplay;