import React, { useCallback, useMemo } from 'react';
import { Modal, Button } from 'antd';
import styled from 'styled-components';
import { useMutation, useQueryClient } from 'react-query';
import { useSelector } from 'react-redux';

import { axiosInstance } from 'services/globalInstance';
import useLocalStorage from 'hooks/useLocalStorage';
import { screenColumnAttributes } from 'components/features/heatmaps/constants';
import { formattedFilters } from 'Utils/ScreenPageFilter';

import compact from 'lodash/compact';
import { useIsAppType } from 'hooks/useIsAppType';
import { getFilterListWithActivityFilterCheck } from 'Utils/helpers/activityFilterUtils';
import { useIsUserV2 } from 'hooks/useUserV2Filter';
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext';

const ModalStyled = styled(Modal)`
  .ant-modal-content {
    border-radius: 8px;
    width: 420;
  }
  .ant-modal-body {
    padding: 36px 40px;
  }
`;

const MainWrapper = styled.div`
  display: flex;
  flex-direction: column;
`;

const StyledConfirm = styled(MainWrapper)`
  margin: 16px 0;
  color: #454b5d;
  font-weight: 400;
  font-size: 13px;
  line-height: normal;
`;

const StyledParagraph = styled(StyledConfirm)``;
const StyledHeading = styled.div`
  display: flex;
  font-weight: 500;
  font-size: 18px;
  line-height: 24px;
  align-items: center;
`;
const StyledError = styled(StyledConfirm)`
  color: #ff4d4f;
`;

const StyledButtonDiv = styled.div`
  display: flex;
  align-items: center;
  justify-content: flex-end;
  margin-top: 16px;
`;

const StyledButton = styled(Button)`
  background: #5d97ff;
  font-weight: 500;
  font-size: 14px;
  padding: 10px 29px;
  border-radius: 6px;
  display: flex;
  align-items: center;
`;

const LinkedButton = styled(StyledButton)`
  color: #5d97ff;
  margin-right: 24px;
  background: #ffffff;
  border-radius: 6px;
  border: none;
`;

const tableInfo = {
  sessionsList: 'sessions',
  aiSessionsList: 'sessions',
  heatmapsList: 'screens',
  eventsList: 'events',
  usersList: 'users',
  nocodeEventsList: 'no_code_event'
};



const EXPORT_CONFIG = {
    exportUrl: `${process.env.PYTHON_API_URL}/csv_export/page_export`,
    getExportUrl(){
        return this.exportUrl;
    }
}

const DownloadDataModal = ({
  visibleDownloadModal,
  handleVisibleModal,
  downLoadColumn,
  setDownloadColumn,
  globalFilter
}) => {
  const queryClient = useQueryClient();
  const isWebSDK = useIsAppType('web');

  let sessionsListReqBody = ''
  let aiSessionListReqBody = ''
  let eventsListReqBody = ''
  let webScreenListReqBody = ''
  let usersListReqBody = ''
  
  try {
    sessionsListReqBody = JSON.parse(
      localStorage.getItem('sessionsListReqBody')
    );
    aiSessionListReqBody = JSON.parse(
      localStorage.getItem('aiSessionsListReqBody')
    );
    eventsListReqBody = JSON.parse(
      localStorage.getItem('eventsListReqBody')
    );
    webScreenListReqBody = JSON.parse(
      localStorage.getItem('webScreenListReqBody')
    );
    usersListReqBody = JSON.parse(localStorage.getItem('usersListReqBody'));
  } catch (err) {
    // silent fail
  }
  const {
    currentAppReducer: { _id: appid },
    appFilter: {
      session: { segment: sessionSegment },
      heatmap: { segment: screenSegment },
      event: { segment: eventSegment },
      user: { segment: userSegment, activityFilterList  },
      dateSegment,
    },
    profileReducer: { email },
    urlReducer: { parentType },
  } = useSelector((state) => state);

  const [headers] = useLocalStorage(isWebSDK ? "webScreenHeaders" : "screenHeaders");
  const [cachedSortBy] = useLocalStorage('screenSortBy');

  const sessionQueryKey = ['sessionItems', sessionsListReqBody];
  const aiSessionQueryKey = ['aiSessionItems', aiSessionListReqBody];
  const eventQueryKey = ['eventList', eventsListReqBody];
  const userQueryKey = ['userList', usersListReqBody];
  const screenQueryKey = ['web-screen-table-list', webScreenListReqBody];
  const sessionResponse = queryClient.getQueryData(sessionQueryKey);
  const aiSessionResponse = queryClient.getQueryData(aiSessionQueryKey);
  const eventListResponse = queryClient.getQueryData(eventQueryKey);
  const userListResponse = queryClient.getQueryData(userQueryKey);
  const screenListResponse = queryClient.getQueryData(screenQueryKey);
  const allNoCodeEvents = queryClient.getQueriesData({queryKey: ['nocodeEventList']});
  const noCodeEventsListResponse = useMemo(() => allNoCodeEvents[0]?.[1] || [], [allNoCodeEvents]);
  const {noCodeEventsFeatureFlag} = useNoCodeEventsContext()

  const getTableLabel = useCallback((table) => {
    if (noCodeEventsFeatureFlag && table === 'nocodeEventsList') {
      return 'smart events';
    } 
    if (noCodeEventsFeatureFlag && table === 'eventsList') {
      return 'coded events';
    }
    return tableInfo[table] || table;
  }, [noCodeEventsFeatureFlag]);

  const sessionListHeaders = useMemo(
    () => sessionResponse?.data?.data?.header || [],
    [sessionResponse]
  );
  const aiSessionListHeaders = useMemo(
    () => aiSessionResponse?.data?.data?.header || [],
    [aiSessionResponse]
  );
  const eventListHeaders = useMemo(
    () => eventListResponse?.data?.data?.header || [],
    [eventListResponse]
  );
  const userListHeaders = useMemo(
    () => userListResponse?.data?.data?.header || [],
    [userListResponse]
  );
  const noCodeEventsListHeaders = useMemo(
    () => noCodeEventsListResponse?.data?.data?.header || [],
    [noCodeEventsListResponse]
   );
  const sessionListOrderBy = useMemo(
    () => sessionResponse?.data?.data?.orderBy || [],
    [sessionResponse]
  );
  const aiSessionListOrderBy = useMemo(
    () => aiSessionResponse?.data?.data?.orderBy || [],
    [aiSessionResponse]
  );
  const eventListOrderBy = useMemo(
    () => eventListResponse?.data?.data?.orderBy || [],
    [eventListResponse]
  );
  const userListOrderBy = useMemo(
    () => userListResponse?.data?.data?.orderBy || [],
    [userListResponse]
  );
  const screenListOrderBy = useMemo(
    () => screenListResponse?.orderBy || [],
    [screenListResponse]
  );
  const noCodeEventsListOrderBy = useMemo(
    () => noCodeEventsListResponse?.data?.data?.orderBy || [],
    [noCodeEventsListResponse]
  );

  const isAllColumnDownload = useMemo(
    () => downLoadColumn === 'allColumns',
    [downLoadColumn]
  );

  const isUserV2 = useIsUserV2();
  
  const userSegmentWithActivityFilterCheck = useMemo(() => getFilterListWithActivityFilterCheck(activityFilterList, userSegment , isUserV2) , [activityFilterList, userSegment, isUserV2]);

  const screenSegmentWithNameFilter = useMemo(() => globalFilter ? [...screenSegment, ...[{
    attribute: "relevant_screen_name",
    operator: "contains",
    value: globalFilter
  }]] : screenSegment, [globalFilter, screenSegment]);

  const segmentFilter = useMemo(() => {
    let filter;
    switch (parentType) {
      case 'sessionsList':
      case 'aiSessionsList':
        filter = [...sessionSegment];
        break;
      case 'heatmapsList':
        filter = [...formattedFilters(screenSegmentWithNameFilter) || []];
        break;
      case 'nocodeEventsList':
      case 'eventsList':
        filter = [...eventSegment];
        break;

      case 'usersList':
        filter = [...userSegmentWithActivityFilterCheck];
        break;
      default:
        filter = [];
    }
    return filter;
  }, [parentType, sessionSegment, screenSegmentWithNameFilter, eventSegment, userSegmentWithActivityFilterCheck]);
  const headersList = useMemo(() => {
    let headersData;
    switch (parentType) {
      case 'sessionsList':
        headersData = [...sessionListHeaders];
        break;
      case 'aiSessionsList':
        headersData = [...aiSessionListHeaders];
        break;
      case 'heatmapsList':
        headersData = [...headers];
        break;
      case 'eventsList':
        headersData = [...eventListHeaders];
        break;
      case 'usersList':
        headersData = [...userListHeaders];
        break;
      case 'nocodeEventsList':
        headersData = [...noCodeEventsListHeaders];
        break;
      default:
        headersData = [];
    }
    return headersData;
  }, [parentType, sessionListHeaders, aiSessionListHeaders, headers, eventListHeaders, userListHeaders, noCodeEventsListHeaders]);
  
  const orderBy = useMemo(() => {
    let requestOrderBy;
    switch (parentType) {
      case 'sessionsList':
        requestOrderBy = [...sessionListOrderBy];
        break;
      case 'aiSessionsList':
        requestOrderBy = [...aiSessionListOrderBy];
        break;
      case 'heatmapsList':
        if( isWebSDK ) {
          requestOrderBy = [...screenListOrderBy];
        } else {
          requestOrderBy = cachedSortBy?.length ? cachedSortBy.map(sortData => ({sortName: screenColumnAttributes[sortData?.id] || sortData?.id , sortOrder: sortData?.desc ? 'desc' : 'asc'})) : [];
        }
        break;
      case 'eventsList':
        requestOrderBy = [...eventListOrderBy];
        break;

      case 'usersList':
        requestOrderBy = [...userListOrderBy];
        break;
      case 'noCodeEventsList':
        requestOrderBy = [...noCodeEventsListOrderBy];
        break;
      default:
        requestOrderBy = [];
    }
    return requestOrderBy;
  }, [parentType, sessionListOrderBy, aiSessionListOrderBy, isWebSDK, eventListOrderBy, userListOrderBy, noCodeEventsListOrderBy, screenListOrderBy, cachedSortBy]);

  const visibleColumnList = useMemo(() => {
    return headersList?.reduce((list, column) => {
      if (column?.isVisible) {
        list.push(column?.attribute);
      }
      return list;
    }, []);
  }, [headersList]);
  
  const allColumnList = useMemo(() => {
    return headersList?.reduce((list, col) => {
      list.push(col?.attribute);
      return list;
    }, []);
  }, [headersList]);
  
  const customUserPropertyColumnList = useMemo(() => {
    return headersList?.filter(column => column?.isCustomUserProperty);
  }, [headersList]);

  const customEventPropteryColumnList = useMemo(() => {
    return headersList?.filter(column => column?.isCustomEventProperty);
  }, [headersList]);
  const visibleCustomUserPropertyColumnList = useMemo(() => {
    return customUserPropertyColumnList?.filter(column => column?.isVisible);
  }, [customUserPropertyColumnList]);

  const visibleCustomEventPropertyColumnList = useMemo(() => {
    return customEventPropteryColumnList?.filter(column => column?.isVisible);
  }, [customEventPropteryColumnList]);
  
  const tableList = useMemo(() => {
    return [`${tableInfo[parentType]}`];
  }, [parentType]);
  
  const columnNameList = useMemo(() => {
    return isAllColumnDownload ? allColumnList : visibleColumnList;
  }, [isAllColumnDownload, allColumnList, visibleColumnList]);
  
  const columnNameListUpdated = useMemo(() => {
    return columnNameList.filter(item => item !== 'displayName');
  }, [columnNameList]);
  
  const screensColumnList = useMemo(() => {
    return columnNameListUpdated?.map(column => screenColumnAttributes[column]);
  }, [columnNameListUpdated]);

  const isWebApp = useIsAppType('web');
  const postBody = useMemo(() => {
    const body = {
      name: 'get_csv_dump',
      appid,
      webApp: isWebApp || false,
      filters: segmentFilter,
      table_list: tableList,
      email_id: email,
      date_range: dateSegment,
      ...(orderBy && { orderBy }),
      customUserPropertyColumns: isAllColumnDownload ? customUserPropertyColumnList.map(item => item.attribute) : visibleCustomUserPropertyColumnList.map(item => item.attribute),
      customEventPropertyColumns: isAllColumnDownload ? customEventPropteryColumnList.map(item => item.attribute) : visibleCustomEventPropertyColumnList.map(item => item.attribute),
    };
    // * CX-1876: Remove name and date_range from the body for user v2
    if(isUserV2){
        delete body.name;
        delete body.date_range;
    }
    if (parentType === 'heatmapsList') {
      body.columns = compact(screensColumnList);
    } else {
      body.columns = columnNameList;
    }
    return body;
  }, [appid, isWebApp, segmentFilter, tableList, email, dateSegment, orderBy, isAllColumnDownload, customUserPropertyColumnList, visibleCustomUserPropertyColumnList, customEventPropteryColumnList, visibleCustomEventPropertyColumnList, isUserV2, parentType, screensColumnList, columnNameList]);  

  const {
    data: response,
    error,
    mutate: downloadSession,
    isLoading: loading,
  } = useMutation(
    (data) =>
      axiosInstance({
        method: 'POST',
        url: EXPORT_CONFIG.getExportUrl( ),
        data,
        withCredentials: true,
      }),
    {}
  );

  const exportData = useMemo(
    () => response?.data || error?.response?.data,
    [response, error]
  );

  const handleDownload = () => {
    downloadSession(postBody);
  };

  const closeModal = () => {
    handleVisibleModal(false);
    setDownloadColumn();
  };

  return (
    <div>
      <ModalStyled
        visible={visibleDownloadModal}
        onCancel={() => closeModal()}
        footer={null}
        destroyOnClose
        closable={false}
      >
        <MainWrapper>
          {!exportData && (
            <div>
              <StyledHeading>{`Export ${getTableLabel(parentType)} table data?`}</StyledHeading>
              <StyledConfirm>
                The exported data will be sent to your email in the CSV format.
              </StyledConfirm>
            </div>
          )}
          {exportData && (
            <div>
              {!exportData?.error && (
                <StyledHeading>Data export successful</StyledHeading>
              )}
              <div>
                {exportData?.error && (
                  <>
                    <StyledHeading>{`Export ${tableList} table data?`}</StyledHeading>
                    <StyledError>
                      {exportData?.error?.message?.message ||
                        exportData?.error?.message ||
                        'Sorry, we are unable to process your request! Please try again later'}
                    </StyledError>
                  </>
                )}
              </div>

              {!exportData?.error && (
                <StyledParagraph>
                  The CSV file link should arrive to your email within a few
                  minutes.
                </StyledParagraph>
              )}
            </div>
          )}
          <StyledButtonDiv>
            {exportData && (
              <StyledButton type="primary" onClick={(e) => closeModal(e)}>
                Done
              </StyledButton>
            )}
            {!exportData && (
              <>
                <LinkedButton type="link" onClick={() => closeModal()}>
                  Cancel
                </LinkedButton>
                <StyledButton
                  loading={loading}
                  type="primary"
                  onClick={() => handleDownload()}
                >
                  Confirm
                </StyledButton>
              </>
            )}
          </StyledButtonDiv>
        </MainWrapper>
      </ModalStyled>
    </div>
  );
};

export default DownloadDataModal;
