/**
 * Custom hook to determine if the current context is using User V2 (when parent type is 'usersList').
 *
 * @returns {boolean} - Returns `true` if the parent type is 'usersList', otherwise `false`.
 */
export const useIsUserV2 = () => {
    const {
        urlReducer,
      } = useSelector((state: { urlReducer: { parentType: string } }) => state);
      const { parentType } = urlReducer

    return parentType === 'usersList'
};


export const useFilterOptionType = (
    parentType
        : keyof typeof mappedFilterOption,
): string => {
    const isUserV2 = useIsUserV2()

    const filterOptionType = useMemo(() => mappedFilterOption[parentType] === 'user' && isUserV2 ?
        'user_v2' : mappedFilterOption[parentType], [isUserV2, parentType]);
 
    return filterOptionType;
};

