/**
 * Custom hook to handle user V2 properties and generate query prefixes.
 *
 * @returns {Object} An object containing the `getQueryPrefix` function.
 */
export const useUserV2Properties = () => {
    const isUserV2 = useIsUserV2();
    const hasSmartEvent = useHasSmartEvents();
     const {
        urlReducer: urlQuery,
      } = useSelector((state: { urlReducer: { parentType: string } }) => state);
    //* 'User Where' query prefix is only valid for usersList
    /**
     * @param {string} attribute - The attribute for which the query prefix is needed.
     * @param {string} [title=''] - Optional title to be used in the query prefix.
     * @returns {string} The query prefix based on the attribute and title.
     */
    const getQueryPrefix = (attribute: string, title = '') => {
        // ----
        if (isUserV2 && attributesWithV2QueryPrefix.has(attribute)) {
            // * Check for kUXCam_UserIdentity, if this key found then rename to Custom user ID
            if(attribute==='kUXCam_UserIdentity'){
                return `custom user ID`;
            };
            if(attribute ==='user_custom_label'){
                return `${userV2QueryPrefix} label`;
            }
            if(attribute ==='user_custom_property'){
                return `${userV2QueryPrefix}  `;
            }   
            if(attribute === 'user_event_count' && !hasSmartEvent){
                return `${userV2QueryPrefix} total event count of user`;
            }
            return `${userV2QueryPrefix} ${title.toLowerCase()}`;
        }
        // * for other parent types
        // * Check for kUXCam_UserIdentity, if this key found then rename to Custom user ID
        if(attribute==='kUXCam_UserIdentity'){
            // return `${userV2QueryPrefix} Custom user ID`;
            return `Custom user ID`;
        };
        return title;
    };

    return {
        getQueryPrefix
    }
}

export const useGetAvailableActivityFilters = () => {
    const { noCodeEventsFeatureFlag } = useNoCodeEventsContext()

    const enabledTypes = useMemo(() => [
        ACTIVITY_FILTER_CATEGORY.SESSION,
        ACTIVITY_FILTER_CATEGORY.CODED_EVENT,
        ...(noCodeEventsFeatureFlag ? [ACTIVITY_FILTER_CATEGORY.SMART_EVENT] : []),
        ACTIVITY_FILTER_CATEGORY.SCREENVISIT,
    ], [noCodeEventsFeatureFlag]);

    const getMatchedActivityFilterAttributes = useCallback((type: ACTIVITY_FILTER_CATEGORY) =>
        Object.keys(activityFilterSelector).filter(
            (item) => activityFilterSelector[item].configuration.type === type
        ), []);

    const availableAttrs = useMemo(() =>
        enabledTypes.flatMap((type) => getMatchedActivityFilterAttributes(type))
        , [enabledTypes, getMatchedActivityFilterAttributes]);

    return availableAttrs;
}
