import React, { useCallback, useState } from 'react';

import { Button } from 'antd';

import {StyledModal, FormContainer} from './styles';

const CustomPropModal = ({
  title,
  subtitle,
  children,
  isModalOpen,
  handleOk,
  handleCancel,
  disabled,
  loading,
  hideButtons,
  containerClassName,
}) => (
  <StyledModal
    visible={isModalOpen}
    onOk={handleOk}
    onCancel={handleCancel}
    centered
    footer={null}
    closable={false}
  >
    <span className={containerClassName}>
        <h2>{title}</h2>
        <p>{subtitle}</p>
    </span>

    <FormContainer onFinish={handleOk}>
      {children}

      {
        hideButtons ? null : (
            <div className="modal-footer">
                <Button
                onClick={() => {
                    handleCancel();
                }}
                type="link"
                >
                Cancel
                </Button>
                <Button
                type="primary"
                htmlType="submit"
                disabled={disabled}
                loading={loading}
                >
                Update
                </Button>
            </div>
        )
      }
    </FormContainer>
  </StyledModal>
);

const useCustomPropModal = () => {
    const [openModal, setOpenModal] = useState(false);

    const CustomPropertyModal = useCallback((
        {
            children,
            title,
            subtitle,
            handleOk,
            handleCancel,
            disabled,
            loading,
            hideButtons,
            containerClassName,
        }
    ) => (
        <CustomPropModal 
            isModalOpen={openModal}
            title={title}
            subtitle={subtitle}
            handleOk={handleOk}
            handleCancel={() => {
                handleCancel && handleCancel();
                setOpenModal(false);
            }}
            disabled={disabled}
            loading={loading}
            hideButtons={hideButtons}
            containerClassName={containerClassName}
        >
            {children}
        </CustomPropModal>
    ), [openModal])

    return {
        openModal,
        setOpenModal,
        CustomPropertyModal,
    }
}

export default useCustomPropModal; 