/* eslint-disable  no-nested-ternary */
import Router from 'next/router';
import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder';

export const goToPage = ({
  page,
  appId,
  sessionid,
  secondarysessionid = '',
  autoplay,
  segment = [],
  parentType,
  eventid,
  starttime,
  expanded,
  uxcamuserid,
  notetab,
  dateSegment
}) => {
  let segmentCopy = [ ...segment ]
  let url = '';
  let query = '';
  const autoPlayPart = autoplay ? '#autoplay' : '';
  if (parentType === 'sessionsList') {
    url = sessionid
      ? `/app/${appId}/sessions/list/${page}/${sessionid}${
          starttime ? `/${starttime}` : notetab ? `/0` : ''
        }${notetab ? `/${notetab}` : ''}?`
      : `/app/${appId}/sessions/list/${page}?`;
    query = `appId=${appId}&parentType=sessionsList${
      sessionid ? `&sessionid=${sessionid}` : ''
    }&sessionpage=${page}${
      starttime ? `&starttime=${starttime}` : ''
    }${notetab ? `&notetab=${notetab}` : ''}`;
  } else if (parentType === 'aiSessionsList') {
    url = sessionid
      ? `/app/${appId}/aisessions/list/${page}/${sessionid}${
          starttime ? `/${starttime}` : notetab ? `/0` : ''
        }${notetab ? `/${notetab}` : ''}?secondarysessionid=${secondarysessionid || sessionid}&`
      : `/app/${appId}/aisessions/list/${page}?`;
    query = `appId=${appId}&parentType=aiSessionsList${
      sessionid ? `&sessionid=${sessionid}` : ''
    }&sessionpage=${page}${
      starttime ? `&starttime=${starttime}` : ''
    }${notetab ? `&notetab=${notetab}` : ''}&secondarysessionid=${secondarysessionid || sessionid}`;
  } else if (parentType === 'eventsList') {
    url = !expanded
      ? `/app/${appId}/events/list/${page}?`
      : `/app/${appId}/events/list/${page}/${sessionid}/${eventid}${
          starttime ? `/${starttime}` : ''
        }`;
    query = `appId=${appId}&parentType=eventsList${
      sessionid ? `&sessionid=${sessionid}` : ''
    }&eventpage=${page}&starttime=${starttime}&eventid=${eventid}`;
  } else if (parentType === 'nocodeEventsList') {
    url = !expanded
      ? `/app/${appId}/smart-events/list/${page}?`
      : `/app/${appId}/smart-events/list/${page}/${sessionid}/${eventid}${
          starttime ? `/${starttime}` : ''
        }`;
    query = `appId=${appId}&parentType=nocodeEventsList${
      sessionid ? `&sessionid=${sessionid}` : ''
    }&eventpage=${page}&starttime=${starttime}&eventid=${eventid}`;
  } else if (parentType === 'heatmapsList'){
    url = `/app/${appId}/screens/list/${page}?`;
    query = `appId=${appId}&parentType=heatmapsList&screenpage=${page}`;
  } else {
    url = uxcamuserid
      ? `/app/${appId}/users/list/${page}/${uxcamuserid}?`
      : `/app/${appId}/users/list/${page}?`;
    query = uxcamuserid
      ? `appId=${appId}&parentType=usersList&userpage=${page}&uxcamuserid=${uxcamuserid}`
      : `appId=${appId}&parentType=usersList&userpage=${page}`;
  }
  if (sessionid) segmentCopy = dateSegment ? [...segmentCopy, ...[{ ...dateSegment }]] : segmentCopy;
  url = urlSegmentEncoder(url, segmentCopy);
  if (sessionid) url = `${url}${autoPlayPart}`;
  Router.push(`/integration?${query}`, url);
};