import { useCallback, useMemo } from "react";
import { useSelector } from "react-redux";

import _ from 'lodash';
import { keyLabelMap } from "components/shared/GlobalFilter/components/utils";

const useCustomProps = () => {
    const { appFilter } = useSelector(state => state);
    const { fetchProperty } = appFilter;
    const eventProperties = fetchProperty.event_custom_property.data || [];
    const userProperties = fetchProperty.user_custom_property.data || [];

    // Done in FE as changing in search attribute response was not possible
    // modify each propertyName to append __UXCAM_CUSTOM_PROPERTY to differentiate between custom and non-custom properties
    const modifiedEventProperties = eventProperties.length && eventProperties.map((item) => `${item}__UXCAM_CUSTOM_PROPERTY`) || [];

    const modifiedUserProperties = userProperties.length && userProperties.map((item) => `${item}__UXCAM_CUSTOM_PROPERTY`) || [];

    return {
        eventProperties: modifiedEventProperties,
        userProperties: modifiedUserProperties,
    }
}

export function removeUxCamCustomProperty(val) {
    if (!val) return val;
    if (Array.isArray(val)) {
        const modifiedVal = val.map(item => item.replace(/__UXCAM_CUSTOM_PROPERTY/g, ''))
        return modifiedVal;
    }
    return val.replace(/__UXCAM_CUSTOM_PROPERTY/g, '');
}
// * CX-2366 used to remove the custom property suffix from the key
// * and map it to the label if it exists in the keyLabelMap
export const stripCustomPropertyAndMapLabel = (key) => {
    return keyLabelMap[removeUxCamCustomProperty(key)] || removeUxCamCustomProperty(key);
}; 

const useCustomPropsUtils = ({headers, modalType, selectedCustomProps, overallSelectedCustomProps}) => {
    const { userProperties, eventProperties } = useCustomProps();
    // Select options for custom properties
    const customPropertiesSelectOptions = useMemo(() => {
    if (modalType === 'user') {
        return userProperties;
    } 
        return eventProperties;
    
    }, [modalType, userProperties, eventProperties]);

    // Custom properties
    const overallCustomProps = useMemo(() => [...userProperties, ...eventProperties], [userProperties, eventProperties]);

    const customPropKey = useMemo(() => {
    if (modalType === 'user') {
        return 'isCustomUserProperty';
    } 
        return 'isCustomEventProperty';
    
    }, [modalType]);

    const existingCustomUserProps = useMemo(() => _.filter(headers, { isCustomUserProperty: true }).map(item => item.attribute), [headers]);

    const existingCustomEventProps = useMemo(() => _.filter(headers, { isCustomEventProperty: true }).map(item => item.attribute), [headers]);

    const customProps = useMemo(() => [...existingCustomUserProps, ...existingCustomEventProps, ...selectedCustomProps], [existingCustomEventProps, existingCustomUserProps, selectedCustomProps]);
    const existingCustomProps = useMemo(() => _.uniq(customProps), [customProps]);

    const checkedArray = headers.filter((item) => item.isVisible);
    const uncheckedSortedArray = headers
      .filter((item) => !item.isVisible)
      .sort((a, b) => a.title.localeCompare(b.title));

    const customPropsPresentInHeader = useCallback((customType) => {
        switch(customType) {
            case 'event':
                return _.map(_.filter(headers, { 'isCustomEventProperty': true }), 'attribute');
            default:
                return _.map(_.filter(headers, { 'isCustomUserProperty': true }), 'attribute');
        } 
    }, [headers])

    // returns unselected/remaining custom props not in selectedCustomProps
    const unselectedCustomProps = useMemo(() => _.difference(overallCustomProps, overallSelectedCustomProps), [overallCustomProps, overallSelectedCustomProps]);

    // returns only the selected custom props not present in headers to prevent duplication
    const selectedCustomPropsArray = useMemo(() => _.difference(existingCustomProps, _.map(headers, 'attribute')).map(
            item => ({
              attribute: item,
              title: item,
              subTitle: null,
              isVisible: true,
              isDraggable: true,
              isSortable: true,
              smallSessionTable: false,
              type: "string",
              titleInfo: `Custom ${modalType} property`,
              position: 2,
              [customPropKey]: true,
            })
          ), [existingCustomProps, headers, customPropKey, modalType]);

    const sortedPositionArray = [...checkedArray, ...selectedCustomPropsArray, ...uncheckedSortedArray ];

    // uniqBy to prevent any duplicate values of objects
    const headersWithAddedCustomProps = useMemo(() => _.uniqBy(headers.concat(selectedCustomPropsArray), 'attribute'), [headers, selectedCustomPropsArray]);

     // for removal of objs that was removed from custom props select;
    const filterOutUnslectedCustom = _.filter(headersWithAddedCustomProps, item => !_.includes(unselectedCustomProps, item.attribute));
    const filteredOutPositionArray = useMemo(() => _.filter(sortedPositionArray, item => !_.includes(unselectedCustomProps, item.attribute)), [unselectedCustomProps, sortedPositionArray]);

    const getColumnUpdateObject = useCallback((obj) => {
        const defaults = {
            attribute: obj.attribute,
            isVisible: obj.isVisible,
        };

        if(obj.isCustomEventProperty) {
            return {
                ...defaults,
                isCustomEventProperty: obj.isCustomEventProperty,
            }
        } if (obj.isCustomUserProperty) {
            return {
                ...defaults,
                isCustomUserProperty: obj.isCustomUserProperty,
            }
        } return defaults;
    }, [])

    return {
        customPropsPresentInHeader,
        unselectedCustomProps,
        filterOutUnslectedCustom,
        filteredOutPositionArray,
        customPropertiesSelectOptions,
        getColumnUpdateObject,
        existingCustomProps,
        existingCustomEventProps,
        existingCustomUserProps,
        removeUxCamCustomProperty,
        stripCustomPropertyAndMapLabel
    }
}

const generateLocalHeadersData = ( headers, data ) => {
    let customPropertyPositionIndex = 1000
    const lol =  Object.values( data?.visibility || {} ).map( obj => {
        const { attribute: objAttribute, isVisible, isCustomUserProperty } = obj
        const position = ( data?.position || [] ).findIndex( el => el === objAttribute )

        if ( isCustomUserProperty ) {
            if ( !isVisible ) {
                return undefined
            }
            const newObj = {
                attribute: objAttribute,
                isCustomUserProperty: true,
                isDraggable: true,
                isSortable: true,
                isVisible,
                position: position || customPropertyPositionIndex,
                smallSessionTable: false,
                subTitle: null,
                title: objAttribute,
                titleInfo: "Custom user property",
                type: "str"
            }
            if ( !position ) {
                customPropertyPositionIndex += 1
            }
            return newObj
        }
        const headerObj = headers.find( ( { attribute } ) => attribute === objAttribute )
        return {
            ...headerObj,
            position,
            isVisible: isVisible || false,
        }
    } )
    return lol.filter( el => el )
}

export { useCustomProps, useCustomPropsUtils, generateLocalHeadersData };