import { getStatsBoxes, getUniqueUserBox, loadGraph, statsDropdownOptions } from "redux/actions/sessionStatistics";
import { trackPageViews } from "redux/actions/trackingReport";
import { findIndex, omit } from "lodash";
import { useDispatch, useSelector } from "react-redux";
import { getTimezoneOffset } from "Utils/DateConversion/dateConversionUtils";
import { removeValuesFromFilters } from "Utils/helpers/commonUtils";

const chartEventNames = {
  'session_count_' : 'generate_sessions_chart',
  'session_unique_user_count_': 'generate_total_users_chart',
  'session_new_users_count_': 'generate_new_users_chart',
  'session_is_crashed_sum': 'generate_total_crashes_chart',
  'session_is_crashed_percentage': 'generate_crashes_frequency_chart',
  'session_rage_number_sum': 'generate_total_ragetaps_chart',
  'session_rage_number_avg': 'generate_average_ragetaps_chart',
  'session_duration_sum': 'generate_total_timeinapp_chart',
  'session_duration_avg': 'generate_average_timeinapp_chart',
  'session_screen_number_sum': 'generate_total_screenvisits_chart',
  'session_screen_number_avg': 'generate_average_screenvisits_chart',
  // updated screen visits attributes
  'session_screen_count_sum': 'generate_total_screenvisits_chart',
  'session_screen_count_avg': 'generate_average_screenvisits_chart',
  // updated rage taps attributes
  'session_rage_gesture_count_sum': 'generate_total_ragetaps_chart',
  'session_rage_gesture_count_avg': 'generate_average_ragetaps_chart',
}

const useSessionAnalyticsAPI = () => {
  const dispatch = useDispatch();
  const { sessionStatisticsReducer : 
    { 
      groupingOptions,
      aggregation_list: aggregationList,
      group_list: groupList, 
      series_plot_options: seriesPlotOptions
    },
    urlReducer: { appId: appid, parentType },
    appFilter
  } = useSelector((state) => state);

  const filters = [ ...appFilter.session.segment ]

  const { dateSegment } = appFilter;

  const groupingOptionsApi = ( isWebApp ) => dispatch(statsDropdownOptions({ appid, webApp: isWebApp }));

  const callStatsBoxes = (filterArgs) => {
    const segment =  filterArgs || filters
    const dynamicPayload = () => ({
      appid,
      filters: [ ...segment ],
      date_range: { ...appFilter.dateSegment }
    })
    const payload = dynamicPayload();
    const payloadByUserBox = dynamicPayload();
    dispatch(getStatsBoxes(payload));
    dispatch(getUniqueUserBox(payloadByUserBox));
  }

  const callGraphApi = (args, filterArgs) => {
    const { grpList, seriesPlotsOptions, agg_list: aggList } = args || {};
    const graphOption = seriesPlotsOptions || seriesPlotOptions;
    const segment =  filterArgs || filters;
    let groupListNew =  groupList ? [...groupList] : [];
    if(grpList) groupListNew = grpList;
    if(groupListNew.length) {
      const periodIndx = findIndex(groupListNew, { attribute:  'session_period' })
      if(periodIndx > -1) groupListNew[periodIndx]['attribute'] = 'session_period_day'
    }
    
    // * CX-2255 -add timezone offset to groupByList 
    groupListNew = groupListNew.map((item) => {
        return {
                    ...item,
                    time_zone_offset: getTimezoneOffset(dateSegment.tz, new Date())
                }
      }
    )
    
    const payload = {
      appid,
      aggregation_list: aggList ? [aggList] : [aggregationList],
      group_list: groupListNew,
      filters: [ ...segment ],
      date_range: { 
        ...appFilter.dateSegment,
        timezoneOffset: getTimezoneOffset(dateSegment.tz, new Date() )
      },
      series_plot_options: omit(
        graphOption,
        'display',
        'key',
        'img'
      ),
    }
    dispatch(loadGraph(payload));
    const { group_list: trackGrpList, filters: trackFilters, dateRange: trackDateRange, aggregation_list: trackAggList } = payload;
    parentType === 'sessionStatistics' && dispatch(trackPageViews(null, {
      eventName: chartEventNames[`${trackAggList[0].attribute}_${trackAggList[0].operator}`],
      track_type: 'event',
      eventProperty: {
        chartType: seriesPlotOptions?.type || 'bar',
        grouping: trackGrpList,
        filters: removeValuesFromFilters(trackFilters),
        dateRange: trackDateRange,
      }
    }));
  }

  const callAnalyticsApi = async(arg, isWebApp) => {
    await callGraphApi(arg);
    !groupingOptions && groupingOptionsApi( isWebApp )
  }

  return { callAnalyticsApi, callStatsBoxes, callGraphApi }

}

export default useSessionAnalyticsAPI;