import React, { useState, useEffect, useMemo } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { useQueryClient } from 'react-query';

import {
  fetchPlanHatApi,
} from 'redux/actions/common';
import { Icon as LegacyIcon } from '@ant-design/compatible';
import { Form, Button, Input } from 'antd';

import { trackPageViews } from 'redux/actions/trackingReport';
import { gotUserDetail } from 'redux/actions/userList/actionObjects';

import useCustomLabels, { useCustomLabelApi } from 'hooks/useCustomLabels';
import { antIcons } from 'components/svg_files/CustomLabelSvgIcon';

import { StyledModal } from './styles';

export const  getSessionsUserId =  (sessions, sessionLists, queryParam) => sessions.map(sessionId => {
  const result = sessionLists.find(session => session[queryParam] === sessionId);
  return result?.userProperty?.uxcamuserid
}).filter( el => el )

export const getSessionsUploadDate =  (sessions, sessionLists, queryParam) => sessions.map(sessionId => {
  const result = sessionLists.find(session => session[queryParam] === sessionId);
  return result?.sessionUploadedDateTime
}).filter( el => el )

const FormItem = Form.Item;

const CustomLabelModel = (props) => {
  const dispatch = useDispatch();
  const [form] = Form.useForm();
  const [, forceUpdate] = useState({});
  const queryClient = useQueryClient();

  const {
    urlReducer: urlQuery,
    currentAppReducer: currentApp,
    selectedSessionReducer: selectedSession,
    selectedUserReducer: selectedUser,
    userDetailReducer
  } = useSelector((state) => state);
  const { _id: appId } = currentApp;

  const {
    customLabels,
    checkExistingLabel,
  } = useCustomLabels();
  const {
    addUserLabel,
    addSessionLabel,
  } = useCustomLabelApi();

  const { data: userDetails } = userDetailReducer;

  const {
    isModalVisible,
    modelHide,
    id,
    markMultiple,
    addMultipleCustomLabel,
  } = props;
  const { parentType } = urlQuery;
  const sessionKey = parentType === 'aiSessionsList' ? 'aiSessionItems' : 'sessionItems'
  const sessionBodyKey = parentType === 'aiSessionsList' ? 'aiSessionsListReqBody' : 'sessionsListReqBody'
  let userQueryKey = ''
  let sessionQueryKey = ''

  try {
    userQueryKey = ['userList', JSON.parse(localStorage.getItem('usersListReqBody'))]
    sessionQueryKey = [sessionKey, JSON.parse(localStorage.getItem(sessionBodyKey))]
  } catch (err) {
    // silent fail
  }

  const [selectedIcon, setSelectedIcon] = useState('tag');
  const [submitLoading, setSubmitLoading] = useState(false);
  const { customLabel: userCustomLabel } = userDetails;
  const labelOnUserDetail = useMemo(
    () => userCustomLabel || [],
    [userCustomLabel]
  );

  const updateUserDetail = (labelName) => {
    const newUserDetail = { ...userDetails };
    if (labelOnUserDetail?.includes(labelName)) {
      newUserDetail.customLabel = labelOnUserDetail?.filter(
        (label) => label !== labelName
      );
    } else {
      labelOnUserDetail.push(labelName);
      newUserDetail.customLabel = labelOnUserDetail;
    }
    dispatch(gotUserDetail(newUserDetail));
  };
 

  const handleLabelAddOnUser = ( data) => {
    const payload = { ...data, appid:appId, }
    addUserLabel(payload)
    dispatch(
      trackPageViews(null, {
        eventName: 'add_label',
        track_type: 'event',
        eventProperty: {
          'label name': payload?.customLabelName,
          'user ids': payload?.uxcamuserIds,
          'label_type': 'user',
        },
      })
    );
    queryClient.setQueryData(userQueryKey, (old) => {
        const ids = data?.uxcamuserIds || [];
        const newBody = old.data.data.body.map((el) => {
            if(ids.length && ids.includes(el.uxcamuserid)) {
                return {
                    ...el,
                    customLabel: [...el.customLabel, data.customLabelName],
                }
            }
            return el
        });
        return {
            ...old,
            data: {
                ...old.data,
                data: {
                    ...old.data.data,
                    body: newBody,
                },
            },
        };
    });
    updateUserDetail(data?.customLabelName);
  };

  const handleLabelAddOnSession = (dataBody) => {
    const sessionResponse = queryClient.getQueryData(sessionQueryKey);
    const queryList =  sessionResponse?.data?.data?.body || []
    const sessionIds = dataBody.sessionIds || []

    const sessionUserIds = getSessionsUserId(sessionIds, queryList, 'sessionid')
    const sessionUploadDate = getSessionsUploadDate(sessionIds, queryList, 'sessionid')
    const dataReloaded = {
      ...dataBody,
       appid: appId,
       uxcamuserIds: sessionUserIds,
       uploadedOn: sessionUploadDate
    }

    addSessionLabel(dataReloaded)

    dispatch(
      trackPageViews(null, {
        eventName: 'add_label',
        track_type: 'event',
        eventProperty: {
          'label name': dataReloaded?.customLabelName,
          'session ids': dataReloaded?.sessionIds,
          'label_type': 'session',
        },
      })
    );

    queryClient.setQueryData(sessionQueryKey, (old) => {
      const ids = dataBody?.sessionIds || [];
      const newBody = old.data.data.body.map((el) => {
        if (ids.length && ids.includes(el.sessionid)) {
          const labelsData = el.customLabel ? [...el.customLabel] : [];
          return {
            ...el,
            customLabel: [...labelsData, dataBody.customLabelName],
          };
        }
        return el;
      });
      return {
        ...old,
        data: {
          ...old.data,
          data: {
            ...old.data.data,
            body: newBody,
          },
        },
      };
    });
    dataBody.sessionIds.forEach((sessionId) => {
      const prevData = queryClient.getQueryData(sessionId);
      if (prevData) {
        const customLabel = prevData?.customLabel || [];
        const newLabel = [...customLabel, dataBody.customLabelName];
        queryClient.setQueryData(sessionId, (previousData) => ({
          ...previousData,
          customLabel: newLabel,
        }));
      }
    });
  }

  const tableId = useMemo(() => {
    let returnValue;
    if (id) {
      returnValue = [id];
    } else if ( [ 'sessionsList', 'aiSessionsList' ].includes( parentType ) ) {
      returnValue = selectedSession;
    } else if (parentType === 'usersList') {
      returnValue = selectedUser;
    }
    return returnValue;
  }, [id, parentType]);

  const addLabel = async (ids, value) => {
    const obj = {
      name: value.customLabelName.trim(),
      icon: value.labelIcon,
      sessioncount: 1,
    };
    const userObj = {
      name: value.customLabelName.trim(),
      icon: value.labelIcon,
      usercount: 1,
    };
    const newCustomLabels =
    [ 'sessionsList', 'aiSessionsList' ].includes( parentType )
        ? [...customLabels, obj]
        : [...customLabels, userObj];

    newCustomLabels.sort((a, b) =>
      a.name.localeCompare(b.name)
    );

    if ( [ 'sessionsList', 'aiSessionsList' ].includes( parentType ) ) {
      const combinedData = {
        ...value,
        labelType: 'session',
        sessionIds: ids,
      };
      handleLabelAddOnSession(combinedData)
    } else {
      const combinedData = {
        ...value,
        labelType: 'user',
        uxcamuserIds: ids,
      };
      handleLabelAddOnUser(combinedData)
    }
  };

  const onModelHide = () => {
    form.resetFields();
    modelHide();
  };
  const sessionOrUserKey = [ 'sessionsList', 'aiSessionsList' ].includes( parentType ) ? 'session' : 'user';

  const handleSubmit = async (e) => {
    e.preventDefault();
    e.stopPropagation();
    const values = await form.validateFields();
    const updatedValues = {
      ...values,
      labelIcon: values?.labelIcon || 'tag'
    }

    if (!submitLoading) {
      setSubmitLoading(true);
      dispatch(
        fetchPlanHatApi({ action: `Created ${sessionOrUserKey} label` })
      );
      markMultiple
        ? await addMultipleCustomLabel(values, tableId)
        : await addLabel(tableId, updatedValues);
      setSubmitLoading(false);
      onModelHide();
    }
  };

  const handleLabelExists = (rule, value, callback) => {
    const errors = [];
    if (
      customLabels &&
      checkExistingLabel(value)
    ) {
      errors.push(new Error('Label name already exists.'));
    }
    callback(errors);
  };

  const handleIconClick = (icon) => {
    setSelectedIcon(icon);
  };

  useEffect(() => {
    forceUpdate({});
  }, []);

  useEffect(() => {
    setSelectedIcon('tag');
  }, [])

  useEffect(() => {
    form.setFieldsValue({ [`labelIcon`]: selectedIcon || 'tag' });
  }, [form, selectedIcon]);

  const handleClose = () => {
    setSelectedIcon();
    setSubmitLoading(false);
  };

  return (
    <>
      <StyledModal
        visible={isModalVisible}
        onCancel={onModelHide}
        afterClose={handleClose}
        destroyOnClose
        closable={false}
        footer={null}
      >
        <>
            <h3 className='modal-title'>Create new {sessionOrUserKey} label</h3>

            <Form
            layout="vertical"
            form={form}
            onFinish={handleSubmit}
            hideRequiredMark
            >
            <FormItem
                name="customLabelName"
                rules={[
                { required: true, message: 'Label name is required' },
                { max: 50, message: 'Label name must be less than 50 characters.' },
                { min: 3, message: 'Label name must be more than 2 characters.' },
                { whitespace: true, message: 'Only whitespace are not allowed' },
                { validator: handleLabelExists },
                ]}
            >
                <Input
                autoComplete="off"
                addonBefore={<LegacyIcon type={selectedIcon || 'tag'} />}
                autoFocus
                placeholder="Enter label name"
                />
            </FormItem>
            <FormItem
                label="Select an icon"
                style={{ marginBottom: '0' }}
                name="labelIcon"
                className='select-icon-form'
            >
                <ul className="label-icon-list">
                {antIcons &&
                    antIcons.map((item) => (
                    <li
                        key={item.type}
                        className={
                        item.type === selectedIcon ? 'icon-selected' : ''
                        }
                    >
                        <a href="#!">
                        <LegacyIcon
                            type={item.type}
                            onClick={(e) => {
                            e.preventDefault();
                            e.stopPropagation();
                            handleIconClick(item.type);
                            }}
                        />{' '}
                        </a>
                    </li>
                    ))}
                </ul>
            </FormItem>
            <div className="btn-wrapper">
                <FormItem>
                <Button type="secondary" key="back" onClick={onModelHide}>
                    Cancel
                </Button>
                </FormItem>
                <Form.Item shouldUpdate>
                {() => (
                    <Button
                    key="submit"
                    loading={submitLoading}
                    disabled={
                        !!form
                        .getFieldsError()
                        .filter(({ errors }) => errors.length).length
                    }
                    type="primary"
                    onClick={(e) => handleSubmit(e)}
                    >
                    Done
                    </Button>
                )}
                </Form.Item>
            </div>
            </Form>
        </>
      </StyledModal>
      <style>{`
    .icon-label-input .ant-input-group-addon{
      border-color: #efeff3;
    }
    .create-custom-label-modal .ant-form-item .ant-form-item-label label:after{
      display: none;
    }
    `}</style>
    </>
  );
};

export default CustomLabelModel;
