/* eslint-disable react/jsx-props-no-spreading */
import React, { useEffect, useState, useCallback, memo, useMemo } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import Icon, {
  SettingOutlined,
} from '@ant-design/icons';
import {
  Dropdown,
  message,
  Badge,
} from 'antd';
import Cookies from 'universal-cookie';
import Router from 'next/router';
import Link from 'next/link';
import className from 'classnames';
import { v4 } from 'uuid';
import { useQueryClient } from 'react-query';

import { trackPageViews } from 'redux/actions/trackingReport';
import { gotUserDetail } from 'redux/actions/userList/actionObjects';
import useCustomLabels, { useCustomLabelApi } from 'hooks/useCustomLabels';
import find from 'lodash/find';
import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder';
import CustomLabelMangeModal from 'components/common/CustomLabelManageModel';
import CustomLabelModal, {
  getSessionsUserId,
  getSessionsUploadDate,
} from '../CustomLabelModal';

import LabelsDropdownOverlay from '../LabelsDropdownOverlay';

import { ActionButton, FooterContainer, HeaderContainer } from './styles';

const cookies = new Cookies();
const TagIcon = () => (
  <svg
    width="12"
    height="12"
    viewBox="0 0 12 12"
    fill="none"
    xmlns="http://www.w3.org/2000/svg"
  >
    <path
      d="M6.76224 0.185043C6.70369 0.126283 6.6341 0.0796824 6.55747 0.047925C6.48083 0.0161676 6.39868 -0.000119645 6.31572 6.61653e-07H0.631572C0.464069 6.61653e-07 0.303426 0.0665382 0.184983 0.184976C0.0665404 0.303413 0 0.464049 0 0.631545V6.31545C0 6.48344 0.0663151 6.64385 0.185051 6.76195L5.23763 11.8143C5.29615 11.8732 5.36572 11.9199 5.44235 11.9517C5.51898 11.9836 5.60116 12 5.68415 12C5.76714 12 5.84932 11.9836 5.92595 11.9517C6.00258 11.9199 6.07215 11.8732 6.13067 11.8143L11.8148 6.1304C11.8735 6.0718 11.9201 6.0022 11.9519 5.92559C11.9836 5.84897 12 5.76684 12 5.6839C12 5.60096 11.9836 5.51883 11.9519 5.44221C11.9201 5.3656 11.8735 5.296 11.8148 5.2374L6.76224 0.185043ZM5.68415 10.4748L1.26314 6.05399V1.26309H6.05425L10.4753 5.6839L5.68415 10.4748Z"
      fill="#161E35"
    />
    <path
      d="M3.47115 4.42072C3.9961 4.42072 4.42166 3.99518 4.42166 3.47025C4.42166 2.94532 3.9961 2.51978 3.47115 2.51978C2.94619 2.51978 2.52063 2.94532 2.52063 3.47025C2.52063 3.99518 2.94619 4.42072 3.47115 4.42072Z"
      fill="#161E35"
    />
  </svg>
);

const LabelTagIcon = (data) => <Icon component={TagIcon} {...data} />;

const MarkLabelCell = memo((props) => {
  const dispatch = useDispatch();
  const queryClient = useQueryClient();

  const {
    urlReducer: urlQuery,
    currentOrgReducer: currentOrg,
    currentAppReducer: currentapp,
    userDetailReducer,
  } = useSelector((state) => state);


  const {
    megaFilterCustomLabels: customLabels,
    megaFilteredSessionLabels,
    megaFilterSessionLabels,
    filteredUserLabels,
    userLabels,
    selectedLabels,
    setSelectedLabels,
    labelSearch,
    setLabelSearch,
    resetSearch,
    compareLabels,
  } = useCustomLabels();
  const { markUserLabel, markSessionLabel } = useCustomLabelApi();
  const { parentType, sessionpage, userpage } = urlQuery;
  const isUserList = parentType === 'usersList';
  const [selectedCustomLabelTab, setSelectedCustomLabelTab] = useState(isUserList ? 'user' : 'session');
  const hasCustomLabels = useMemo(
    () =>
      isUserList
        ? userLabels?.length > 0
        : megaFilterSessionLabels?.length > 0,
    [filteredUserLabels, megaFilteredSessionLabels, isUserList])

  const { data: userDetails } = userDetailReducer;
  const { customLabel: userCustomLabel } = userDetails;

  const { crashed, isRageTap, sessionid, uxcamuserid, customLabel, sessionLocked } =
    props.data;

  const { index: i } = props

  const getCrashValue = useCallback(() => {
    if (crashed?.props?.children) {
      return crashed?.props?.children === 'Yes';
    }
    return crashed;
  }, [crashed]);

  const getSessionIdValue = useCallback(() => {
    if (sessionid?.props?.children) {
      return sessionid?.props?.children;
    }
    return sessionid;
  }, [sessionid]);

  const isCrashedValue = getCrashValue();
  const sessioId = getSessionIdValue();
  const isRageTapValue = typeof isRageTap === 'boolean' && isRageTap === true;

  const { rowIndex } = props;
  const { _id } = currentapp;

  const { session, user } = useSelector((state) => state.appFilter);
  const [isModalVisible, setIsModalVisible] = useState(false);
  const [isEditModalVisible, setIsEditModalVisible] = useState(false);
  const [customLabelValue, setCustomLabelValue] = useState(customLabel);
  const [displayIcons, setDisplayIcon] = useState([]);

  const loginInFromGuest = cookies.get('loggedInType');

  const labelOnUserDetail = useMemo(
    () => userCustomLabel || [],
    [userCustomLabel]
  );

  const updateUserDetail = (labelName) => {
    const newUserDetail = { ...userDetails };
    if (labelOnUserDetail?.includes(labelName)) {
      newUserDetail.customLabel = labelOnUserDetail?.filter(
        (label) => label !== labelName
      );
    } else {
      labelOnUserDetail.push(labelName);
      newUserDetail.customLabel = labelOnUserDetail;
    }
    dispatch(gotUserDetail(newUserDetail));
  };

  const showModal = () => {
    setIsModalVisible(true);
  };

  const showEditModal = () => {
    setIsEditModalVisible(true);
  };

  const hideModal = () => {
    setIsModalVisible(false);
    setIsEditModalVisible(false);
  };

  const modalProps = {
    isModalVisible,
    modelHide: hideModal,
    id: [ 'sessionsList', 'aiSessionsList' ].includes( parentType ) ? sessioId : uxcamuserid,
  };

  const editModalProps = {
    isModalVisible: isEditModalVisible,
    modelHide: hideModal,
  };

  const handleClassName = (data) => {
    let classname;
    if (data === 1) {
      classname = 'tag-icon-wrapper icon-one';
    } else if (data === 2) {
      classname = 'tag-icon-wrapper icon-two';
    } else {
      classname = 'tag-icon-wrapper icon-three';
    }
    return classname;
  };

  let url;
  let query;

  switch( parentType ) {
    case 'sessionsList':
      url = `/app/${currentapp['_id']}/sessions/list/${
        sessionpage || 1
      }/${sessioId}?`;
  
      url = urlSegmentEncoder(url, session.segment);
      query = `appId=${
        currentapp['_id']
      }&video=false&parentType=sessionsList&sessionid=${sessioId}&index=${rowIndex}&sessionpage=${
        sessionpage || 1
      }`
      break
    case 'aiSessionsList':
      url = `/app/${currentapp['_id']}/aisessions/list/${
        sessionpage || 1
      }/${sessioId}?`;
  
      url = urlSegmentEncoder(url, session.segment);
      query = `appId=${
        currentapp['_id']
      }&video=false&parentType=aiSessionsList&sessionid=${sessioId}&index=${rowIndex}&sessionpage=${
        sessionpage || 1
      }`
      break
    default:
      url = `/app/${currentapp['_id']}/users/list/${
        userpage || 1
      }/${uxcamuserid}?`;
      url = urlSegmentEncoder(url, user.segment);
      query = `appId=${
        currentapp['_id']
      }&parentType=usersList&uxcamuserid=${uxcamuserid}&index=${rowIndex}&sessionpage=1&userpage=${
        userpage || 1
      }`
  }
  const sessionKey = parentType === 'aiSessionsList' ? 'aiSessionItems' : 'sessionItems'
  const sessionBodyKey = parentType === 'aiSessionsList' ? 'aiSessionsListReqBody' : 'sessionsListReqBody'
  let sessionQueryKey = '';
  try {
    sessionQueryKey = [ sessionKey,JSON.parse(localStorage.getItem( sessionBodyKey )),];
  } catch (err) {
    // silent fail
  }

  const handleMarkLabel = (data, labelType) => {
    const sessionResponse = queryClient.getQueryData(sessionQueryKey);
    const queryList = sessionResponse?.data?.data?.body || [];
    const sessionIds = [sessioId];
    const markLabelName = data.customLabelName;

    const sessionUserIds = getSessionsUserId(
      sessionIds,
      queryList,
      'sessionid'
    );
    const sessionUploadDate = getSessionsUploadDate(
      sessionIds,
      queryList,
      'sessionid'
    );
    const dataReloaded = {
      ...data,
      uxcamuserIds: sessionUserIds,
      sessionIds,
      uploadedOn: sessionUploadDate,
      labelType,
      appid: _id,
    }

    markSessionLabel(dataReloaded);
      
    if ([ 'sessionsList', 'aiSessionsList' ].includes( parentType )) {
      queryClient.setQueryData(sessionQueryKey, (old) => {
        const bodyCopy = [...old.data?.data?.body ?? []];
        const index = bodyCopy.findIndex((el) => el.sessionid === sessionid);
        let sessionObj = bodyCopy[index];
        const value = data.isTagged;
        if (sessionObj.customLabel.indexOf(markLabelName) > -1) {
          if (!value) {
            const customLabelCopy = [...sessionObj.customLabel];
            customLabelCopy.splice(customLabelCopy.indexOf(markLabelName), 1);
            sessionObj = {
              ...sessionObj,
              customLabel: customLabelCopy,
            };
          }
        } else if (value) {
          sessionObj = {
            ...sessionObj,
            customLabel: [...sessionObj.customLabel, markLabelName],
          };
        }

        return {
          ...old,
          data: {
            ...old.data,
            data: {
              ...old.data.data,
              body: bodyCopy.map((el) => {
                if (el.sessionid === sessionObj.sessionid) {
                  return {
                    ...el,
                    customLabel: sessionObj.customLabel,
                  };
                }
                return el;
              }),
            },
          },
        };
      });
    }

    let obj;
    const prevData = queryClient.getQueryData(sessionid);
    if (prevData) {
      const customLabelCopy = prevData?.customLabel || [];
      if (customLabelCopy?.indexOf(markLabelName) > -1) {
        obj = customLabelCopy.filter((item) => item !== markLabelName);
      } else {
        obj = [...customLabelCopy, markLabelName];
      }
      queryClient.setQueryData(sessionid, (previousData) => ({
        ...previousData,
        customLabel: obj,
      }));
    }
  };

  let userQueryKey = '';
  try {
    userQueryKey = [
      'userList',
      JSON.parse(localStorage.getItem('usersListReqBody')),
    ];
  } catch (err) {
    // silent fail
  }


  const handleCustomLabelTabChange = (key) => {
    setSelectedCustomLabelTab(key)
  }

  const handleCustomLabelClick = (key, label) => {
    const selectedLabel = find(label.options, { name: key });
    const selectedKeys = [...customLabelValue, ...selectedLabels.sessionLabels, ...selectedLabels.userLabels]

    if(loginInFromGuest !== 'guest') {
      const keyAlreadyExists = selectedKeys.includes(key)
      const data = {
        'customLabelName': selectedLabel.name,
      }
      if(keyAlreadyExists) {
        setSelectedLabels({
          sessionLabels: selectedLabels.sessionLabels.filter((item) => item !== key),
          userLabels: selectedLabels.userLabels.filter((item) => item !== key),
        })
        data['isTagged'] = false
      } else {
        setSelectedLabels({
          sessionLabels: [...selectedLabels.sessionLabels, key],
          userLabels: [...selectedLabels.userLabels, key],
        })
        data['isTagged'] = true
      }

      if ([ 'sessionsList', 'aiSessionsList' ].includes( parentType )) {
        dispatch(
          trackPageViews(null, {
            eventName: data[selectedLabel.name] ? 'add_label' : 'remove_label',
            track_type: 'event',
            eventProperty: {
              'label name': label.name,
              'session ids': [sessioId],
              'label_type': selectedLabel.labelType,
            },
          })
        );
        handleMarkLabel(data, selectedLabel.labelType);
      } else {
        const payload = {
          ...data,
          labelType: selectedLabel.labelType,
          uxcamuserIds: [uxcamuserid],
          appid: _id,
        };
        markUserLabel(payload);
        dispatch(
          trackPageViews(null, {
            eventName: data[selectedLabel.name] ? 'add_label' : 'remove_label',
            track_type: 'event',
            eventProperty: {
              'label name': label.name,
              'user ids': [uxcamuserid],
              'label_type': selectedLabel.labelType,
            },
          })
        );
        queryClient.setQueryData(userQueryKey, (old) => {
          const bodyCopy = [...old.data?.data?.body ?? []];
          const index = bodyCopy.findIndex(
            (el) => el.uxcamuserid === uxcamuserid
          );
          let userDetailObj = bodyCopy[index];
          const labelName = data.customLabelName;
          const value = data.isTagged;

          if (userDetailObj?.customLabel?.indexOf(labelName) > -1) {
            if (!value) {
              const customLabelCopy = [...userDetailObj.customLabel];
              customLabelCopy.splice(customLabelCopy.indexOf(labelName), 1);
              userDetailObj = {
                ...userDetailObj,
                customLabel: customLabelCopy,
              };
            }
          } else if (value) {
            userDetailObj = {
              ...userDetailObj,
              customLabel: [...userDetailObj.customLabel, labelName],
            };
          }

          return {
            ...old,
            data: {
              ...old.data,
              data: {
                ...old.data.data,
                body: bodyCopy.map((el) => {
                  if (el?.uxcamuserid === userDetailObj?.uxcamuserid) {
                    return {
                      ...el,
                      customLabel: userDetailObj?.customLabel || [],
                    };
                  }
                  return el;
                }),
              },
            },
          };
        });

        if(urlQuery?.uxcamuserid === uxcamuserid){
          updateUserDetail(data.customLabelName);
        }
      }
    } else {
      message.info(
        'You are not allowed to perform this action from the guest login.'
      );
    }
  }

  const redirectNext = (e, queryParam, urlParam, sessionId, val) => {
    const cookieFromAdmin = cookies.get('loggedInFromAdminDashboard');
    if (
      e.target.id === 'outside-icon-box' ||
      e.target.id === 'stack-icon-box' ||
      val === 'stack-icon'
    ) {
      if (cookieFromAdmin !== '1' && currentOrg.planFeature !== null) {
        const link = (
          <Link
            href={{
              pathname: '/integration',
              query: {
                setting: 'org_setting',
                org: currentOrg.orgId,
                org_tab: 'plan',
                parentType: 'settings',
              },
            }}
            as={`/settings/org/${currentOrg.orgId}/plan`}
            legacyBehavior
          >
            <a href="#!">
              {' '}
              {currentOrg.status.toLowerCase() === 'expired'
                ? 'Renew your Plan'
                : 'Update your Plan '}
            </a>
          </Link>
        );
        if (
          (parentType === 'usersList' &&
            currentOrg.planFeature.userAnalysis === 0) ||
          (parentType === 'usersList' &&
            currentOrg.status.toLowerCase() === 'expired')
        ) {
          const validationMessage = (
            <strong>
              Your plan{' '}
              {currentOrg.status.toLowerCase() === 'expired'
                ? 'has been expired'
                : 'does not allow for User Analysis'}
              .<br />
              Please {link} to enable this feature.
            </strong>
          );

          message.info(validationMessage);
          return;
        }
      }

      Router.push(`/integration?${queryParam}`, `${urlParam}`);
    }
  };

  const handleIconCount = useMemo(() => {
    const defaultIconCount = 0;

    if (customLabelValue instanceof Array && customLabelValue.length > 0) {
      customLabelValue.map(() => defaultIconCount + 1);
    }
    return defaultIconCount;
  }, [customLabelValue]);

  const handleIconDisplay = useCallback(() => {
    const displayIcon = [];
    displayIcon.push(
      <span key={v4()} className="icon-item">
        <Badge count={handleIconCount} title={false}>
          <LabelTagIcon
            className={isRageTapValue || isCrashedValue ? 'label-default' : ''}
          />
        </Badge>
      </span>
    );
    setDisplayIcon(displayIcon);
  }, [handleIconCount, isCrashedValue, isRageTapValue]);

  useEffect(() => {
    handleIconDisplay();
  }, [customLabelValue, customLabels?.length]);

  useEffect(() => {
    setCustomLabelValue(
      customLabel || []
    );
    if (parentType === 'usersList') setSelectedCustomLabelTab('user');
  }, [customLabel, customLabel?.length]);

  const handleLabelSearch = useCallback((e) => {
    const { value } = e.target;
    if(selectedCustomLabelTab === 'session') {
      setLabelSearch({
        ...labelSearch,
        sessionLabels: value
      })
    } else {
      setLabelSearch({
        ...labelSearch,
        userLabels: value
      })
    }
  }, [labelSearch, selectedCustomLabelTab, setLabelSearch])

  const labelTabs = useMemo(() => (
    parentType === 'usersList' ? [
      {
          key: 'user',
          name: 'User label',
          options: filteredUserLabels.sort((a, b) => compareLabels(customLabelValue, a, b)), // includes filtered labels
          showSearch: true,
      }
    ] : [
      {
          key: 'session',
          name: 'Session label',
          options: megaFilteredSessionLabels.sort((a, b) => compareLabels(customLabelValue, a, b)), // includes filtered labels
          showSearch: true,
      },
    ]
  ), [customLabelValue, filteredUserLabels, megaFilteredSessionLabels, parentType])

  const renderFooter = loginInFromGuest !== 'guest' && (
    <FooterContainer>
      <ActionButton onClick={showModal}>
        <i className="anticon" style={{ fontWeight: '500', fontSize: '20px' }}>
          +
        </i>{' '}
        Add label
      </ActionButton>
      {hasCustomLabels && (
        <ActionButton onClick={showEditModal}>
          <SettingOutlined /> Manage label
        </ActionButton>
      )}
    </FooterContainer>
  );

  const renderHeader = useMemo(
    () =>
      isCrashedValue || isRageTapValue ? (
        <HeaderContainer>
          <span className="title">
            UX issues:{' '}
            {
              isCrashedValue && (
                <em>Crashed {isRageTapValue && ', '}</em>
              )
            }
            {
              isRageTapValue && (
                <em>With rage tap</em>
              )
            }
          </span>
        </HeaderContainer>
      ) : null,
    [isCrashedValue, isRageTapValue]
  );

  const handeEmptyMessageDisplay = useMemo(() => {
    if (isUserList && !hasCustomLabels) {
      return 'You haven’t created any label.';
    }
    if (customLabels && customLabels.length <= 0) {
      return 'You haven’t created any label.';
    }
    return null;
  }, [customLabels, hasCustomLabels, isUserList]);

  return (
    <>
      <div
        aria-hidden="true"
        id="outside-icon-box"
        onClick={(e) => redirectNext(e, query, url, sessioId)}
        className={className('icon-flex-box')}
      >
        <div
          className={handleClassName(displayIcons.length)}
          data-intercom-target={i === 0 ? 'Label icon' : null}
        >
          <Dropdown
            destroyPopupOnHide
            // overlay={ sessionLocked ? <></> : menu }
            overlay={
              sessionLocked ? (
                <></>
              ) : (
                <LabelsDropdownOverlay
                  tabs={labelTabs}
                  selectedKeys={[
                    ...customLabelValue,
                    ...selectedLabels.sessionLabels,
                    ...selectedLabels.userLabels,
                  ]}
                  handleItemClicked={handleCustomLabelClick}
                  handleTabChange={handleCustomLabelTabChange}
                  searchInput={{
                    placeholder: 'Search label',
                    value:
                      selectedCustomLabelTab === 'session'
                        ? labelSearch.sessionLabels
                        : labelSearch.userLabels,
                    onChange: handleLabelSearch,
                  }}
                  hideFooter
                  footer={renderFooter}
                  header={renderHeader}
                  emptyMessage={
                    handeEmptyMessageDisplay
                  }
                  headerStyle={{
                    backgroundColor: '#F3F4F5',
                    padding: '8px 10px',
                  }}
                  containerStyle={{
                    paddingTop:
                      isRageTapValue || isCrashedValue ? '0px' : '10px',
                  }}
                />
              )
            }
            onVisibleChange={(visible) => {
              if (!visible) {
                resetSearch();
                setSelectedLabels({
                  sessionLabels: [],
                  userLabels: [],
                });
              }
            }}
            overlayClassName="label-dropdown-menu"
          >
            <a
              href="#!"
              className="stack-icon-box"
              id="stack-icon-box"
              onClick={
                !sessionLocked
                  ? (e) => redirectNext(e, query, url, sessioId, 'stack-icon')
                  : () => null
              }
            >
              <span key={v4()} className="icon-item">
                <Badge count={handleIconCount} title={false}>
                  <LabelTagIcon
                    className={
                      isRageTapValue || isCrashedValue ? 'label-default' : ''
                    }
                  />
                </Badge>
              </span>
            </a>
          </Dropdown>
        </div>
      </div>

      {!sessionLocked && (
        <>
          {/* Modal for adding custom label */}
          <CustomLabelModal {...modalProps} />
          {/* Modal for editing custom label */}
          <CustomLabelMangeModal {...editModalProps} />
        </>
      )}
    </>
  );
});
export default memo(MarkLabelCell);
