/* eslint-disable no-nested-ternary */
import { Tooltip } from "antd";
import React, { useMemo } from "react";
import { getUserId } from "Utils/helpers/userIdUtils";

export const useUserName = (
    details: {
        customUserId: string | undefined,
        uxcamuserid: string,
    },
    CustomComponent?: React.ComponentType<{ children: React.ReactNode, className?: string ,style?: React.CSSProperties}>
) => {
    const getUserName = useMemo(() => {
        const userIdConfig = getUserId({
            customUserId: details?.customUserId,
            uxcamuserid: details?.uxcamuserid
        });
        return (
            !userIdConfig?.customUserId ?
                <Tooltip
                    title={
                        <span>
                            {userIdConfig?.info}
                        </span>
                    }
                >
                    {CustomComponent ? (
                        <CustomComponent className="text-ellipsis text-italic-asterisk">
                           {userIdConfig?.uxcamuserid}
                        </CustomComponent>
                    ) : (
                        <span className="text-ellipsis text-italic-asterisk" >
                           {userIdConfig?.uxcamuserid}
                        </span>
                    )}
                </Tooltip>
                :
                CustomComponent ? (
                    <CustomComponent className="text-ellipsis">
                        {userIdConfig?.customUserId}
                    </CustomComponent>
                ) : (
                    <span className="text-ellipsis">
                        {userIdConfig?.customUserId}
                    </span>
                )
        );
    }, [details, CustomComponent]);
    return getUserName;
};
