import React, { memo } from 'react'
import { Modal } from 'antd'

const DeleteSession = ({
  onOk,
  onCancel,
  title,
  deleteModalVisible,
  deleteLoading,
  content
}) => {
  const handleOk = () => onOk()
  const handleCancel = () => onCancel()
  return (
    <Modal
      title={title}
      visible={deleteModalVisible}
      onOk={handleOk}
      confirmLoading={deleteLoading}
      onCancel={handleCancel}
      okText='Yes'
      okType='danger'
      cancelText='Cancel'
      maskClosable={false}
    >
      <p>{content}</p>
    </Modal>
  )
}
export default memo(DeleteSession)
