const ShareSessionModal = ({ shareMultiple, selectedSession, alternativeStyle=false, hidePublicLink=false }) => {
  const dispatch = useDispatch();

  const { urlReducer: urlQuery } = useSelector((state) => state);
  const { timeRef, videoElemRef } = useSessionVideoControlls();

  const [visible, setVisible] = useState(false);
  const [checkedList, setCheckedList] = useState(true);
  const [privateMessage, setPrivateMessage] = useState('');
  const [displayedPlayerTime, setDisplayedPlayerTime] = useState();
  const [emails, setEmails] = useState([]);
  const [timeChecked, setTimeChecked] = useState(true);
  const [shareLoading, setShareLoading] = useState(false);
  const [buttonClicked, setButtonClicked] = useState(false);
  const [shareLinkClicked, setShareLinkClicked] = useState(false);

  const sessions = React.useMemo( () => shareMultiple ? selectedSession : [urlQuery.secondarysessionid || urlQuery.sessionid], [ shareMultiple, selectedSession, urlQuery.sessionid, urlQuery.secondarysessionid ] )

  const title = useMemo(() => {
    if ( !shareMultiple ) return 'Share the session';
    if ( selectedSession?.length ) return 'Share selected sessions';
    return 'Share the session';
  }, [ selectedSession, shareMultiple ]);

  const videoDuration = videoElemRef?.current?.duration || 0
  const playerTime = useMemo(
    () =>
      displayedPlayerTime !== '' ? timeFormatToSecond(displayedPlayerTime) : -1,
    [displayedPlayerTime]
  );

  const {
    isLoading: loading,
    isFetched: fetched,
    data,
    refetch,
  } = useShareSessionLink(['shareSessionLink', sessions], {
    appId: urlQuery.appId,
    sessions,
  });

  const hasPublicUrlShareAccess = useMemo(()=> data?.data?.data?.publicUrl?.length >= 1, [data])

  const {
    isLoading,
    isSuccess,
    isError,
    error,
    data: sharedData,
    refetch: refetchShareSession,
  } = useShareSessions(['shareSessions', sessions], {
    sessions,
    appId: urlQuery.appId,
    privateMessage,
    email: emails,
    isPublic: hasPublicUrlShareAccess && checkedList,
    ...(playerTime > 0 && { viewTime: playerTime }),
  });

  const publicUrl = useMemo(
    () => data?.data?.data?.publicUrl?.join('\n'),
    [data]
  );
  const privateUrl = useMemo(
    () => data?.data?.data?.privateUrl?.join('\n'),
    [data]
  );

  const formattedVideoTime = useMemo(
    () => secondsToTime(timeRef?.current),
    [timeRef]
  );

  const isValidTime = useMemo(() => {
    if (
      matchRegex.test(displayedPlayerTime) ||
      !Number.isNaN(displayedPlayerTime)
    ) {
      return playerTime <= videoDuration;
    }
    return false;
  }, [playerTime, videoDuration, displayedPlayerTime]);

  const getShareUrl = React.useCallback( ( tempTimeChecked ) => {
    const shareUrl = checkedList && hasPublicUrlShareAccess ? publicUrl : privateUrl;
    if ( shareMultiple ) return shareUrl;
    if ( playerTime > 0 && ( timeChecked || tempTimeChecked ) ) return `${ shareUrl }/${ playerTime }`;
    return shareUrl;
  }, [ checkedList, hasPublicUrlShareAccess, playerTime, privateUrl, publicUrl, shareMultiple, timeChecked ] )

  const shareUrl = React.useMemo( () => getShareUrl(), [ getShareUrl ] )

  const setVisibleModal = React.useCallback( (value) => {
    if (!value) {
      setButtonClicked(false);
      setDisplayedPlayerTime(0);
      setEmails([]);
      setPrivateMessage('');
      setTimeChecked(true);
      setCheckedList(true)
    }
    setVisible(value);
  }, [] )

  const copyLink = React.useCallback( (e, tempTimeChecked) => {
    e?.stopPropagation();
    e?.preventDefault();
    const urlToShare = getShareUrl( tempTimeChecked );
    navigator.clipboard.writeText(urlToShare);
    message.success('Sessions link has been copied.');
    dispatch(trackPageViews(null, {
      eventName: 'copy_sharing_link',
      track_type: 'event',
      eventProperty: {
        redesignFlag: true,
        sessionid: sessions,
        linkType: checkedList && hasPublicUrlShareAccess ? 'public' : 'private',
        buttonType: 'inside_share_dialog'
      }
    }))
    dispatch(
      fetchPlanHatApi({ action: 'Shared session', info: { method: 'link' } })
    );
    setVisibleModal(false);
  }, [ dispatch, sessions, setVisibleModal, getShareUrl, checkedList, hasPublicUrlShareAccess ] )

  const handlePrivateMessage = React.useCallback( (e) => {
    setPrivateMessage(e.target.value);
  }, [] )

  const showShareSessionModal = useCallback(() => {
    setButtonClicked(true);
    refetch();
    
    dispatch(trackPageViews(null, {
      eventName: 'open_session_sharing_dialog',
      track_type: 'event',
      eventProperty: {
        redesignFlag: true
      }
    }))
  }, [refetch, dispatch] );

  const handleTimeChange = React.useCallback( (e) => {
    const initialTime = isEmpty(e.target.value) ? '' : e.target.value;
    setDisplayedPlayerTime(initialTime);
  }, [] )

  const handleShareSession = React.useCallback( () => {
    setShareLoading(true)
    refetchShareSession();
    dispatch(
      fetchPlanHatApi({ action: 'Shared session', info: { method: 'email' } })
    );
    dispatch(trackPageViews(null, {
        eventName: 'session_shared_by_email',
        track_type: 'event',
        eventProperty: {
          redesignFlag: true,
          sessionid: sessions,
          email: emails,
        }
      }))
  }, [ refetchShareSession, dispatch, emails, sessions ] )

  useEffect(() => {
    setDisplayedPlayerTime(formattedVideoTime);
  }, [formattedVideoTime]);

  const updateDisplayedTime = useCallback(() => {
    const timeValue =  secondsToTime(timeRef?.current)
    setDisplayedPlayerTime(timeValue);
  }, [timeRef])

  const handleModalDisplay = useCallback(()=>{
    setVisibleModal(true);
    updateDisplayedTime()
  },[updateDisplayedTime, setVisibleModal])

  useEffect(() => {
    if (data && buttonClicked) {
      handleModalDisplay()
    }
  }, [data, buttonClicked, handleModalDisplay]);

  useEffect(() => {
    if (isSuccess) {
      message.success('Session successfully shared.');
    }
    if (isError) {
      message.error(error?.response.data.error.message);
    }
    setVisibleModal(false);
    setShareLoading( false )
  }, [sharedData, error, isError, isSuccess, setVisibleModal]);

  const handleEmails = React.useCallback( ( val ) => {
    setEmails( val )
  }, [] )

  const handleGetLabel = React.useCallback( ( email, index, removeEmail ) => (
    <div data-tag key={ index }>
      { email }
      <span
        aria-hidden="true"
        data-tag-handle
        onClick={() => removeEmail( index ) }
      >
        ×
      </span>
    </div>
  ), [] )

  const handleCheckedList = React.useCallback( ( e ) => {
    setCheckedList( e.target.checked )
  }, [] )

  const handleCheckedTime = React.useCallback( ( e ) => {
    setTimeChecked( e.target.checked )
  }, [] )

  const handleModalCancel = React.useCallback( () => {
    setVisibleModal(false);
  }, [ setVisibleModal ] )
  
  const handleLinkButton = React.useCallback( () => {
    refetch()
    setShareLinkClicked( true )
    updateDisplayedTime()
    dispatch(trackPageViews(null, {
      eventName: 'copy_sharing_link',
      track_type: 'event',
      eventProperty: {
        redesignFlag: true,
        sessionid: sessions,
        linkType: checkedList && hasPublicUrlShareAccess ? 'public' : 'private',
        buttonType: 'outside_share_dialog'
      }
    }))
  }, [ refetch, dispatch, updateDisplayedTime, sessions, checkedList, hasPublicUrlShareAccess ] )
  
  React.useEffect( () => {
    if ( shareLinkClicked && fetched ) {
      copyLink( undefined, shareLinkClicked )
      setShareLinkClicked( false )
    }
  }, [ shareLinkClicked, fetched, copyLink ])

  return (
    <>
      <GlobalStyle />
      <ModalWrapper>
        <span>
          <Tooltip
            title="Share session"
            placement="bottom"
            align={{ offset: [0, 0] }}
          > {
              alternativeStyle ?
                <ButtonRound2  
                    data-intercom-target="Share Session Button"
                    onClick={ showShareSessionModal }
                    disabled={ loading }
                >
                    { loading && buttonClicked ? <Spin indicator={ <LoadingOutlined style={{ fontSize: 14 }} spin /> } /> : <img src="/static/sharing/share-primary.svg" alt="share icon" /> }
                </ButtonRound2>
                :
              <ButtonPrimary
                data-intercom-target="Share Session Button"
                onClick={ showShareSessionModal }
                disabled={ loading }
              >
                { loading && buttonClicked ? <Spin indicator={ <LoadingOutlined style={{ fontSize: 14 }} spin /> } /> : <img src="/static/sharing/share.svg" alt="share icon" /> }
                Share
              </ButtonPrimary>
            }   
          </Tooltip>
          <Tooltip
            title="A public link for sharing the session outside your team in UXCam."
            overlayClassName='custom-popover share-link-popover'
            placement="bottomRight"
            align={{ offset: [8, 0] }}
          >
          {
          hidePublicLink ? null :
          alternativeStyle ? 
            <ButtonRound2
                data-intercom-target="Share Session Link"
                onClick={ handleLinkButton }
                disabled={ loading }
                >
                { loading && shareLinkClicked ? <Spin indicator={ <LoadingOutlined style={{ fontSize: 14 }} spin /> } /> : <img src="/static/sharing/chain.svg" alt="" /> }
            </ButtonRound2>
          :
          <ButtonRound
            data-intercom-target="Share Session Link"
            onClick={ handleLinkButton }
            disabled={ loading }
            >
            { loading && shareLinkClicked ? <Spin indicator={ <LoadingOutlined style={{ fontSize: 14 }} spin /> } /> : <img src="/static/sharing/chain.svg" alt="" /> }
          </ButtonRound>
        }
          </Tooltip>
          <Modal
            visible={ visible }
            centered
            closable={ false }
            className="new-share-session-modal"
            maskStyle={ { backgroundColor: 'rgba(22, 30, 53, 0.3)' } }
            disabled={ !isValidTime || emails.length === 0 || isLoading }
            footer={
              [
                <Button
                  key="back"
                  type="secondary"
                  onClick={ handleModalCancel }
                >
                  Cancel
                </Button>,
                <Button
                  key="submit"
                  type="primary"
                  disabled={ !isValidTime || emails.length === 0 || isLoading || shareLoading }
                  loading={ shareLoading }
                  onClick={ handleShareSession }
                >
                  { shareLoading ? "Sharing" : "Share" }
                </Button>
              ]
            }
          >
            <ModalTitle>
              { title }
            </ModalTitle>
            <ModalLinkWrapper>
              <ModalLink value={ shareUrl } readOnly />
              <CopyToClipboard text={ shareUrl } >
                <ModalLinkImgButton onClick={ copyLink }>
                  <ModalLinkIcon src="/static/sessions/link.svg" />
                </ModalLinkImgButton>
              </CopyToClipboard>
              <CopyToClipboard text={ shareUrl } >
                <ModalLinkButton
                  disabled={ !isValidTime }
                  onClick={ copyLink }
                >
                  Copy link
                </ModalLinkButton>
              </CopyToClipboard>
              
            </ModalLinkWrapper>
            <Field>
              <FieldTitle>
                Recipients
              </FieldTitle>
              <ReactMultiEmail
                placeholder="Add people"
                emails={ emails }
                onChange={ handleEmails }
                getLabel={ handleGetLabel }
              />
            </Field>
            <Field>
              <FieldTitle>
                Message
              </FieldTitle>
              <TextAreaWrapperRedesigned
                placeholder="Add a message"
                autoSize={ { minRows: 1, maxRows: 4 } }
                value={ privateMessage }
                onChange={ handlePrivateMessage }
              />
              <Checkboxes>
                { hasPublicUrlShareAccess && (
                  <CheckboxWrapper>
                    <Tooltip
                      title="Check this box only if you also want to make the session replay accessible to people who don’t have access to your app’s UXCam account."
                      overlayStyle={{ zIndex: '999999' }}
                    >
                      <Checkbox
                        onChange={ handleCheckedList }
                        checked={ checkedList }
                      />
                      <CheckboxTitle>Generate public link</CheckboxTitle>
                    </Tooltip>
                  </CheckboxWrapper>
                ) }
                { !shareMultiple && (
                  <CheckboxWrapper>
                    <CheckboxWrapperTop>
                      <Checkbox
                        onChange={ handleCheckedTime }
                        checked={timeChecked}
                      />
                      <CheckboxTitle>Shared session starts at:</CheckboxTitle>
                      <InputNumericStyled
                        id="time"
                        disabled={!timeChecked}
                        placeholder="00:00"
                        value={ displayedPlayerTime }
                        onChange={ handleTimeChange }
                      />
                    </CheckboxWrapperTop>
                    { !isValidTime && timeChecked && (
                      <ErrorMeesageRedesigned>Please enter valid time</ErrorMeesageRedesigned>
                    ) }
                  </CheckboxWrapper>
                ) }
              </Checkboxes>
            </Field>
          </Modal>
        </span>
      </ModalWrapper>
    </>
  );
};

export default React.memo( ShareSessionModal )
