import React from 'react';
import { Modal, Button } from 'antd';

import {LimitMessageBox, ModalBody, ModalHeader, StyledImg, LinkButton} from './styles';

const UpgradeModal = ({
    upgradePlan,
    handleUpgrade,
    handleGetinTouch,
    handleCancel,
    acceptText
}) => (
    <Modal
        visible={upgradePlan}
        onCancel={() => handleCancel()}
        footer={null}
        className="limit-message-box"
        width="520px"
      >
        <LimitMessageBox>
          <ModalHeader>
            <StyledImg src="/static/uxcam-new-logo.svg" alt="" />
          </ModalHeader>
          <ModalBody>
            <p>
              Please upgrade your plan to enable this feature or get in touch
              with the customer success team.
            </p>
          </ModalBody>

          <>
            <Button type="primary" onClick={() => handleUpgrade()}>
              {acceptText || 'Request Pricing'}
            </Button>

            <LinkButton type="link" onClick={() => handleGetinTouch()}>
              Get in touch
            </LinkButton>
          </>
        </LimitMessageBox>
      </Modal>
  )

export default UpgradeModal;