import moment from 'moment/moment';

const DatesMapper = {
  screenFlow:'2022-03-15'
}

export const removeMilliseconds = (value, type) => {
  if(type === 'start') return `${moment.utc(value).startOf('day').toISOString().split('.')[0]}Z`
  return `${moment.utc(value).endOf('day').toISOString().split('.')[0]}Z`
}

export const disabledDate = (current, payload) => {
  const { parentType, checkFlag } = payload;
  if (parentType === 'screenFlow' && current && checkFlag) {
    return current < moment(DatesMapper['screenFlow']) || current > moment().endOf('day')  ;
  }
  return current && current > moment().endOf('day')
}

export const isDateOlderThanMonths = ( sessionUploadedDateTime, monthsOfVideosAccessible ) => {
  const sessionAgeInMonths = moment( new Date() ).diff( new Date( sessionUploadedDateTime ), 'months', true )
  return monthsOfVideosAccessible && sessionAgeInMonths > monthsOfVideosAccessible
}