import React, { useMemo, memo, useCallback } from 'react';
import { useDispatch } from 'react-redux';
import styled, { css } from 'styled-components';
import { useSessionVideoContext } from 'components/shared/Sessions/Context';
import { fetchPlanHatApi } from 'redux/actions/common';
import { formatTime } from 'components/shared/Sessions/Video/utils';
import PlayLockIcon from 'public/static/lock-features/player-lock-icon.svg';

import PauseVideoIcon from 'public/static/session-replay/play-white.svg';
import PlayVideoIcon from 'public/static/session-replay/paused.svg';
import NoVideoIcon from 'public/static/session-replay/no-video.svg';
import { useUserName } from 'hooks/useUserName';

const Item = styled.div`
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  gap: 12px;
  padding-right: 10px;
  background-color: transparent;
  border: none;
  &:focus,
  button:focus {
    outline: none;
  }
`;

const ButtonAndTime = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 48px;
  min-width: 48px;

  button {
    margin: 0;
    padding: 0;
    cursor: pointer;
    background-color: transparent;
    border: none;
    display: flex;
  }

  span {
    font-size: 12px !important;
  }

  ${ ( { locked } ) => locked && css`
    button {
      cursor: default;
    }
  `}
`;

const UserAndSessions = styled.div`
  display: flex;
  flex-direction: column;
  white-space: nowrap;
  font-weight: 400 !important;
  text-align: left;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  gap: 4px;
  .text-ellipsis {
   font-size: 12px !important;
   overflow: hidden;
   text-overflow: ellipsis;
   white-space: nowrap;
   color: #090F19;
  }
  span {
    font-size: 11px !important;
    font-weight: 400;
    line-height: 0.9rem;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
`;

const SessionListItem = ({
  user,
  duration,
  sessionsNum,
  sessionId,
  onPlay,
  onPause,
  selectedItem,
  video,
  isViewed,
  sessionLocked,
}) => {
  const dispatch = useDispatch()
  const { isPlaying: videoPlaying, userTime } = useSessionVideoContext();
  const isActive = useMemo(()=> sessionId === selectedItem, [sessionId, selectedItem] ) ;
  const isPlaying = useMemo(()=> isActive && (videoPlaying), [isActive, videoPlaying]) ;
  const formattedTime = useMemo(
    () => formatTime(duration),
    [duration]
  );

  const handlePlay = useCallback(
    (e) => {
      e.stopPropagation();
      onPlay({ sessionId, isActive: !isActive, isViewed, userTime });
      dispatch(fetchPlanHatApi({ action: 'played video from session page' }))
    },
    [onPlay, sessionId, isActive, isViewed, userTime, dispatch]
  );

  const handlePause = useCallback(
    (e) => {
      e.stopPropagation()
      onPause({ sessionId })
    },
    [onPause, sessionId]
  );
  const UserName = useUserName({
    customUserId: user?.kUXCam_UserIdentity,
    uxcamuserid: user?.uxcamuserid,
  });
  const getIcon = useMemo(() => {
    if (video) {
      return isPlaying ? <PauseVideoIcon id='play-icon' /> : <PlayVideoIcon id='play-icon' />;
    }
    return <NoVideoIcon id='play-icon' />;
  }, [isPlaying, video])
  return (
    <Item role="button" tabIndex="0" className='session-list-item'>
      <ButtonAndTime locked={ sessionLocked }>
            <button
              type="button"
              onMouseDown={
                ( video && !sessionLocked ) ? (isPlaying ? handlePause : handlePlay) : () => null }
            >
              {
                sessionLocked ? (
                  <PlayLockIcon 
                    height={ 24 }
                    width={ 24 }
                    alt="play icon locked"
                  />
                ) : (
                  getIcon
                )
              }
            </button>
            <span className='subtitle'>{formattedTime}</span>
      </ButtonAndTime>
      <UserAndSessions>
        {UserName}
        <span className='subtitle'>{`Session ${sessionsNum}`}</span>
      </UserAndSessions>
    </Item>
  );
};

export default memo(SessionListItem);
