// convert to video precision
export const toVideoTime = (time) =>
  Math.ceil((time + Number.EPSILON) * 100_000) / 100_000;

export const formatTime = (seconds) => {
  const useSeconds = seconds < 0 ? 0 : seconds;
  const guide = seconds;
  let s = Math.floor(useSeconds % 60);
  let m = Math.floor((useSeconds / 60) % 60);
  let h = Math.floor(useSeconds / 3600);
  const gm = Math.floor((guide / 60) % 60);
  const gh = Math.floor(guide / 3600);

  // handle invalid times
  if (Number.isNaN(seconds) || seconds === Infinity) {
    // '-' is false for all relational operators (e.g. <, >=) so this setting
    // will add the minimum number of fields specified by the guide
    // eslint-disable-next-line no-multi-assign
    h = m = s = '-';
  }

  // Check if we need to show hours
  // eslint-disable-next-line prefer-template
  h = h > 0 || gh > 0 ? h + ':' : '';

  // If hours are showing, we may need to add a leading zero.
  // Always show at least one digit of minutes.
  // eslint-disable-next-line prefer-template
  m = ((h || gm >= 10) && m < 10 ? '0' + m : m) + ':';

  // Check if leading zero is need for seconds
  // eslint-disable-next-line prefer-template
  s = s < 10 ? '0' + s : s;

  return h + m + s;
};

export const findOrientationOverlayByTime = (overlays, findTime) => {
  let start = 0;
  let end = overlays.length - 1;
  // Iterate while start not meets end
  while (start <= end) {
    // Find the mid index
    const mid = Math.floor((start + end) / 2);

    // If element is present at mid, return True
    const midOverlay = overlays[mid];
    const { start: startTime, end: endTime } = midOverlay;
    const found = findTime >= startTime && findTime <= endTime;
    if (found) return midOverlay;

    // Else look in left or right half accordingly
    if (startTime < findTime) start = mid + 1;
    else end = mid - 1;
  }

  return undefined;
};

export const createOrientationOverlays = (overlay, duration) => {
  // find all orientation changes in overlay (g=10)
  const orientationChanges = overlay.filter(({ g }) => g === 10);

  // in case there is no orientation changes, we can fill the whole overlay
  // with the same orientation, picked from first entry in overlay
  if (!orientationChanges.length) {
    return overlay.length ? [ {
      start: overlay[0].start,
      end: duration || overlay[overlay.length - 1].end,
      o: overlay[0].o,
    } ] : []
  }

  return orientationChanges.map(({ start, end, o }) => ({ start, end, o }));
};

export const findGesturesByTime = (gestures, findTime) => {
  let lowerIndex = -1;
  let upperIndex = -1;

  let start = 0;
  let end = gestures.length - 1;
  // find first gesture matching the time treshhold
  while (start <= end) {
    // Find the mid index
    const mid = Math.floor((start + end) / 2);

    // If element is present at mid, return True
    const { time } = gestures[mid];
    const endTime = time + 0.5;
    const found = findTime >= time && findTime <= endTime;

    if (found) {
      start = mid;
      lowerIndex = mid;
      upperIndex = mid;
      break;
    }

    // Else look in left or right half accordingly
    if (time < findTime) start = mid + 1;
    else end = mid - 1;
  }

  if (lowerIndex === -1) {
    return [];
  }

  // find lower bound
  while (lowerIndex >= 0) {
    // eslint-disable-next-line no-plusplus
    const prevGesture = gestures[lowerIndex - 1];
    if (!prevGesture) {
      break;
    }

    const { time } = prevGesture;
    const prevFound = time + 0.5 >= findTime;

    if (prevFound) {
      lowerIndex -= 1;
    } else {
      break;
    }
  }

  // find upper bound
  while (upperIndex <= end) {
    // eslint-disable-next-line no-plusplus
    const nextGesture = gestures[upperIndex + 1];
    if (!nextGesture) {
      break;
    }

    const { time } = nextGesture;
    const nextFound = time <= findTime;

    if (nextFound) {
      upperIndex += 1;
    } else {
      break;
    }
  }

  return gestures.slice(lowerIndex, upperIndex + 1);
};

export const getMilliSecondsPad = (num, size) => `000${num}`.slice(size * -1);

export const getActivityDisplayTime = (seconds) => {
  const oneDay = 24 * 60 * 60; // number of seconds in a day
  const oneHour = 60 * 60; // number of seconds in an hour
  const oneMinute = 60; // number of seconds in a minute

  // Calculate the number of whole days, hours, minutes, and seconds
  // const days = Math.floor(seconds / oneDay);
  const hours = Math.floor((seconds % oneDay) / oneHour);
  const minutes = Math.floor((seconds % oneHour) / oneMinute);
  const wholeSeconds = Math.floor(seconds % oneMinute);

  // Calculate the remaining milliseconds
  const milliseconds = (seconds % 1)
    .toFixed(3)
    .slice(2)
    .toString()
    .padEnd(3, '0');

  // add '0' if minutes and seconds is in single digits
  const displayMinutes = minutes.toString().padStart(2, '0');
  const displaySeconds = wholeSeconds.toString().padStart(2, '0');

  // get milliseconds in single digit
  const withSingleDigitMilliseconds = Number(String(milliseconds)[0]);

  // Construct a string representation of the time
  const timeString = `${
    hours > 0 ? `${hours}:` : ''
  }${displayMinutes}:${displaySeconds}.${withSingleDigitMilliseconds}`;

  return timeString;
};


export const mapAppLogsWithScreen = (screenTimeline, logsTimeline) => {
  let activeIndex = 0;
  if (logsTimeline.length === 0) return [];

  return screenTimeline.map(({ activityName, time, endTime }) => {
    const logs = logsTimeline.slice(activeIndex).filter(({ timeLine }) => {
      if (timeLine >= time && timeLine <= endTime) {
        activeIndex += 1;
        return true;
      }
      return false;
    });

    return { activityName, time, endTime, logs };
  });
};

