import React, { useEffect, useState } from 'react';
import { Button, Modal } from 'antd';
import { useSelector } from 'react-redux';

import { showIntercom } from 'Utils/constants/index';
import { useSessionTimeLine } from './Context';

const CommonLimitModal = () => {
  const [modalVisible, setModalVisible] = useState(false);
  const [videoLimitPopupText, setVideoLimitPopupText] = useState('');
  const { currentOrgReducer: currentOrg } = useSelector((state) => state);
  const { sessionDetail, setVideoLimitPopup, videoLimitPopup } =
    useSessionTimeLine();
  const handleCancel = () => {
    setModalVisible(false);
    setVideoLimitPopup(false);
  };

  const openVideoLimitPopup = () => {
    setModalVisible(true);
    if (sessionDetail?._id && !sessionDetail?.isPlayable) {
      setVideoLimitPopupText(
        'You have exceeded the monthly session quota limit allowed on your plan. You can upgrade your plan to increase the limits and again be able to view your sessions.'
      );
    }

    if (sessionDetail?.verifiedPastVideoRecordingLimit) {
      setVideoLimitPopupText(
        `This video has been recorded after your plan's video recording limit has been reached. Gain access to watch the video by simply upgrading your plan.`
      );
    }
  };

  useEffect(() => {
    videoLimitPopup && !modalVisible && openVideoLimitPopup();
  }, [videoLimitPopup]);

  return (
    <Modal
      visible={modalVisible}
      onCancel={handleCancel}
      footer={null}
      afterClose={handleCancel}
      destroyOnClose
      className="limit-message-box"
    >
      <div className="modal-header">
        <img
          src="/static/uxcam-new-logo.svg"
          alt=""
          style={{ width: '100px' }}
        />
      </div>
      <div className="modal-body">
        <p>{videoLimitPopupText}</p>
      </div>

      <div className="modal-footer">
        <a
          href={`${process.env.REDIRECT_URL}/settings/org/${currentOrg?.orgId}/plan`}
          className="ant-btn ant-btn-primary"
        >
          Upgrade
        </a>
        <Button
          onClick={() => showIntercom()}
          style={{ textDecoration: ' underline ' }}
        >
          Get in touch
        </Button>
      </div>
    </Modal>
  );
};

export default CommonLimitModal;
